            break;

          case '\\\\':
            rep = "\\\\\\\\";
            replen = 2;
            break;

          case '\\n':
            rep = "\\\\n";
            replen = 2;
            break;

          case '\\r':
            rep = "\\\\r";
            replen = 2;
