/* web_tool console styling.
 *
 * Layout C: four cards in a row, a permanent log pane below that can be
 * dragged taller.  The point of the shape is that pressing a button and seeing
 * what it did in the log are visible at the same time -- a log on another tab
 * turns every action into two steps and an act of memory.
 *
 * Narrow screens fall back to a single column rather than shrinking the cards
 * until the tables overflow.
 *
 * Degraded mode greys the cards that cannot work over serial alone instead of
 * hiding them: a control that disappears looks like a bug, and one that is
 * present but dead is worse.  Greyed out and labelled is the honest option.
 */

:root {
  --bg: #12151a;
  --card: #1b2028;
  --edge: #2b323d;
  --fg: #d8dee9;
  --dim: #8b96a5;
  --ok: #7ec87e;
  --bad: #e06c75;
  --warn: #e5c07b;
  --accent: #61afef;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  background: var(--bg);
  color: var(--fg);
  font: 13px/1.5 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

body {
  display: flex;
  flex-direction: column;
}

#statusbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  background: #0d1014;
  border-bottom: 1px solid var(--edge);
  flex: 0 0 auto;
  flex-wrap: wrap;
}

.sep { color: var(--dim); }
.grow { flex: 1 1 auto; }
.warn { color: var(--warn); }

.lamp {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--bad);
  display: inline-block;
}
.lamp.on { background: var(--ok); }
.lamp.idle { background: var(--dim); }

#cards {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  padding: 8px;
  flex: 1 1 auto;
  min-height: 120px;
  overflow: auto;
}

.card {
  background: var(--card);
  border: 1px solid var(--edge);
  border-radius: 6px;
  padding: 8px 10px;
  min-width: 0;
  overflow: auto;
}

.card.disabled {
  opacity: 0.4;
  pointer-events: none;
}

.card h2 {
  margin: 0 0 6px;
  font-size: 13px;
  color: var(--accent);
}

.card h3 {
  margin: 10px 0 4px;
  font-size: 12px;
  color: var(--dim);
}

.row {
  display: flex;
  gap: 4px;
  align-items: center;
  margin: 4px 0;
}
.row.wrap { flex-wrap: wrap; }

button, select, input {
  background: #232a34;
  color: var(--fg);
  border: 1px solid var(--edge);
  border-radius: 4px;
  padding: 3px 7px;
  font: inherit;
}
button { cursor: pointer; }
button:hover { border-color: var(--accent); }
button.mini { padding: 1px 6px; font-size: 12px; }
button.danger { border-color: #6b3238; color: #f0a0a6; }
input { min-width: 0; }

.meta {
  color: var(--dim);
  font-size: 12px;
  white-space: pre-wrap;
  word-break: break-all;
  margin: 4px 0 0;
}

table { width: 100%; border-collapse: collapse; }
td {
  padding: 1px 3px;
  vertical-align: top;
  word-break: break-all;
}
td.k { color: var(--accent); white-space: nowrap; }
td.masked { color: var(--warn); }

.previewbox {
  position: relative;
  background: #05070a;
  border: 1px solid var(--edge);
  border-radius: 4px;
  min-height: 110px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.previewbox img { max-width: 100%; display: none; }
#preview-none { color: var(--dim); }

#dragger {
  height: 6px;
  cursor: row-resize;
  background: var(--edge);
  flex: 0 0 auto;
}
#dragger:hover { background: var(--accent); }

#logpane {
  display: flex;
  flex-direction: column;
  height: 260px;
  flex: 0 0 auto;
  min-height: 60px;
  border-top: 1px solid var(--edge);
}

#logbar {
  display: flex;
  gap: 6px;
  align-items: center;
  padding: 4px 8px;
  background: #0d1014;
  flex: 0 0 auto;
}

#log {
  margin: 0;
  padding: 6px 8px;
  overflow: auto;
  flex: 1 1 auto;
  white-space: pre-wrap;
  word-break: break-all;
  font-size: 12px;
}

#log .drop { color: var(--warn); }
#log .err { color: var(--bad); }
#log .me { color: var(--accent); }

@media (max-width: 1100px) {
  #cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 640px) {
  #cards { grid-template-columns: 1fr; }
}

/* web_tool console front end.
 *
 * Talks only to this backend: JSON over the WebSocket's text frames, JPEG over
 * its binary frames.  It does not know that TCP or a serial port exist, which
 * is what lets the transport change without touching the page.
 *
 * Frames are handed to <img> through URL.createObjectURL, so a 30 KB JPEG stays
 * 30 KB instead of the 40 KB it would become as base64.
 */

'use strict';

const $ = (id) => document.getElementById(id);

let ws = null;
let nextId = 1;
const pending = new Map();
let paused = false;
let lastObjectUrl = null;
let logLines = [];
let filterText = '';

/* ---- transport ------------------------------------------------------- */

function connect() {
  const proto = location.protocol === 'https:' ? 'wss:' : 'ws:';
  ws = new WebSocket(proto + '//' + location.host + '/ws');
  ws.binaryType = 'arraybuffer';

  ws.onopen = () => addLog('me', 'console: 已连接后端');
  ws.onclose = () => {
    addLog('err', 'console: 与后端断开，2s 后重连');
    setLamp('lamp-tcp', false);
    $('tcp-text').textContent = '后端断开';
    setTimeout(connect, 2000);
  };
  ws.onmessage = (ev) => {
    if (typeof ev.data === 'string') { onText(JSON.parse(ev.data)); }
    else { onBinary(new Uint8Array(ev.data)); }
  };
}

function send(obj) {
  return new Promise((resolve, reject) => {
    if (!ws || ws.readyState !== 1) { reject(new Error('后端未连接')); return; }
    const id = nextId++;
    obj.id = id;
    pending.set(id, resolve);
    ws.send(JSON.stringify(obj));
    setTimeout(() => {
      if (pending.has(id)) { pending.delete(id); reject(new Error('后端超时')); }
    }, 30000);
  });
}

async function cmd(name, args) {
  const rsp = await send({ op: 'cmd', cmd: name, args: args || {} });
  if (rsp && rsp.ok === false) {
    /* The errname, not the number: ENOENT tells an operator the key is not
     * set; -2 tells them nothing. */
    addLog('err', 'cmd ' + name + ' 失败: ' + rsp.err +
           ' (' + (rsp.errname || rsp.errno) + ')');
  }
  return rsp;
}

function onText(msg) {
  if (msg.type === 'rsp') {
    const fn = pending.get(msg.id);
    if (fn) { pending.delete(msg.id); fn(msg); }
    return;
  }
  if (msg.type === 'log') {
    const e = msg.event || {};
    if (e.dropped !== undefined) {
      addLog('drop', '--- 丢弃 ' + e.dropped + ' 行日志 ---');
      $('dropped').textContent = 'dropped=' + (msg.dropped_total || 0);
    } else if (e.exit !== undefined) {
      addLog('me', '--- 命令结束，exit=' + e.exit + ' ---');
    } else if (e.line !== undefined) {
      addLog('', e.line);
    }
    return;
  }
  if (msg.type === 'state') { renderState(msg.state); return; }
  if (msg.type === 'bootstrap') { renderBootstrap(msg); return; }
}

function onBinary(buf) {
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const seq = view.getUint32(0, true);
  const digest = view.getUint32(4, true);
  const jpeg = buf.subarray(8);

  if (lastObjectUrl) { URL.revokeObjectURL(lastObjectUrl); }
  lastObjectUrl = URL.createObjectURL(new Blob([jpeg], { type: 'image/jpeg' }));
  const img = $('preview');
  img.src = lastObjectUrl;
  img.style.display = 'block';
  $('preview-none').style.display = 'none';
  $('cam-meta').textContent =
    'seq ' + seq + ', ' + jpeg.length + ' 字节, fnv1a 0x' +
    digest.toString(16).padStart(8, '0');
}

/* ---- rendering ------------------------------------------------------- */

function setLamp(id, on, idle) {
  const el = $(id);
  el.classList.toggle('on', !!on);
  el.classList.toggle('idle', !!idle);
}

function renderState(st) {
  const link = st.link || {};
  setLamp('lamp-tcp', link.connected);
  $('tcp-text').textContent = link.connected
    ? 'TCP 已连 ' + link.host + ':' + link.port
    : '重连中（第 ' + (link.attempts || 0) + ' 次）' +
      (link.last_error ? ' — ' + link.last_error : '');

  const ser = st.serial || {};
  setLamp('lamp-serial', false, !ser.held);
  $('serial-text').textContent = ser.held
    ? '串口被本工具占用（serial_cmd.sh/autoflash.sh 会失败）'
    : '串口已释放' + (ser.holder ? '（被他人占用）' : '');

  $('fps-text').textContent = (st.fps || 0).toFixed(1) + ' fps';
  $('dropped').textContent = st.dropped_total
    ? 'dropped=' + st.dropped_total : '';

  const cap = st.capture || {};
  $('cap-meta').textContent = cap.recording
    ? '正在落盘 ' + cap.name + '：' + cap.frames + ' 帧，' +
      cap.rejected + ' 帧校验失败，' + cap.log_lines + ' 行日志'
    : '未在录制';

  const tb = $('sessions').tBodies[0];
  tb.innerHTML = '';
  (st.sessions || []).forEach((s) => {
    const tr = tb.insertRow();
    tr.insertCell().textContent = s.name;
    tr.insertCell().textContent = s.frames + ' 帧';
    const c = tr.insertCell();
    c.textContent = s.rejected ? s.rejected + ' rejected' : '';
    if (s.rejected) { c.className = 'masked'; }
  });

  /* Serial cannot do preview or the structured settings, so those cards are
   * greyed instead of silently failing. */
  const degraded = !link.connected;
  $('card-preview').classList.toggle('disabled', degraded);
  $('card-kvdb').classList.toggle('disabled', degraded);
  $('card-control').classList.toggle('disabled', degraded);
  $('degraded').textContent = degraded
    ? (st.degraded_reason || '仅串口可用：预览与结构化设置不可用')
    : '';
}

function renderBootstrap(msg) {
  addLog('me', 'bootstrap: ' + (msg.ok ? '成功（' + msg.path + '，' +
        msg.ip + '）' : '失败：' + (msg.degraded_reason || '')));
  (msg.steps || []).forEach((s) => {
    addLog('', '  ' + (s.ok ? '[ok]  ' : '[fail]') + ' ' + s.step +
           (s.ip ? ' ' + s.ip : '') + ' — ' + (s.detail || ''));
  });
}

function addLog(cls, text) {
  logLines.push({ cls, text });
  if (logLines.length > 4000) { logLines = logLines.slice(-3000); }
  if (paused) { return; }
  renderLog();
}

function renderLog() {
  const el = $('log');
  const atBottom = el.scrollTop + el.clientHeight >= el.scrollHeight - 20;
  const frag = document.createDocumentFragment();
  logLines
    .filter((l) => !filterText || l.text.indexOf(filterText) >= 0)
    .slice(-1500)
    .forEach((l) => {
      const span = document.createElement('span');
      if (l.cls) { span.className = l.cls; }
      span.textContent = l.text + '\n';
      frag.appendChild(span);
    });
  el.innerHTML = '';
  el.appendChild(frag);
  if (atBottom) { el.scrollTop = el.scrollHeight; }
}

/* ---- kvdb ------------------------------------------------------------ */

async function refreshKvdb() {
  const rsp = await cmd('kvdb.list', { raw: $('kvdb-raw').checked });
  const tb = $('kvdb-table').tBodies[0];
  tb.innerHTML = '';
  if (!rsp || !rsp.ok) { return; }
  (rsp.data.items || []).forEach((it) => {
    const tr = tb.insertRow();
    const k = tr.insertCell();
    k.textContent = it.key;
    k.className = 'k';
    const v = tr.insertCell();
    v.textContent = it.value;
    if (it.masked) { v.className = 'masked'; }
  });
  $('kvdb-meta').textContent = rsp.data.persistent
    ? '写入会保留到复位之后'
    : '注意：flash 后端不可用，写入仅本次启动有效';
}

/* ---- wiring ---------------------------------------------------------- */

function wire() {
  $('btn-bootstrap').onclick = () => send({ op: 'bootstrap' });
  $('btn-serial-hold').onclick = () =>
    send({ op: 'serial', action: 'acquire' }).then((r) => {
      if (!r.ok) { addLog('err', r.err); }
    });
  $('btn-serial-free').onclick = () => send({ op: 'serial', action: 'release' });

  $('btn-cam-start').onclick = async () => {
    const [w, h] = $('cam-size').value.split('x').map(Number);
    await cmd('camera.start', { width: w, height: h });
  };
  $('btn-cam-stop').onclick = async () => {
    const r = await cmd('camera.stop');
    if (r && r.ok) {
      addLog('me', 'camera: 发出 ' + r.data.frames_sent + ' 帧，丢弃 ' +
             r.data.frames_dropped + ' 帧');
    }
  };
  $('btn-grab').onclick = async () => {
    /* One frame is the stream started and stopped again; the driver paces at
     * 5 fps either way, so there is nothing a dedicated single-shot path would
     * do differently. */
    const [w, h] = $('cam-size').value.split('x').map(Number);
    await cmd('camera.start', { width: w, height: h });
    setTimeout(() => cmd('camera.stop'), 600);
  };
  $('btn-rec-start').onclick = async () => {
    await send({ op: 'capture', action: 'start' });
    const [w, h] = $('cam-size').value.split('x').map(Number);
    await cmd('camera.start', { width: w, height: h });
  };
  $('btn-rec-stop').onclick = async () => {
    await cmd('camera.stop');
    await send({ op: 'capture', action: 'stop' });
  };

  $('btn-kvdb-refresh').onclick = refreshKvdb;
  $('kvdb-raw').onchange = refreshKvdb;
  $('btn-kvdb-set').onclick = async () => {
    const key = $('kvdb-key').value.trim();
    const value = $('kvdb-value').value;
    if (!key) { return; }
    const r = await cmd('kvdb.set', { key, value });
    if (r && r.ok) {
      addLog('me', 'kvdb: ' + key + (r.data.persistent
        ? ' 已写入 flash' : ' 仅本次启动有效'));
      refreshKvdb();
    }
  };

  $('btn-wifi-connect').onclick = async () => {
    const ssid = $('wifi-ssid').value.trim();
    const psk = $('wifi-psk').value;
    if (!ssid) { return; }
    $('wifi-meta').textContent = '正在关联并请求地址…';
    const r = await cmd('wifi.connect', { ssid, psk });
    if (r && r.ok) {
      $('wifi-meta').textContent = (r.data.running ? '已连接 ' : '未就绪 ') +
        r.data.ip + ' / ' + r.data.netmask + ' gw ' + r.data.gw;
    }
  };

  document.querySelectorAll('[data-shell]').forEach((btn) => {
    btn.onclick = async () => {
      const line = btn.getAttribute('data-shell');
      addLog('me', '$ ' + line);
      const r = await cmd('shell.exec', { cmdline: line });
      if (r && r.ok === false && r.err === 'busy') {
        addLog('err', '已有命令在跑，先停止它');
      }
    };
  });

  $('btn-shell').onclick = async () => {
    const line = $('shell-cmd').value.trim();
    if (!line) { return; }
    addLog('me', '$ ' + line);
    await cmd('shell.exec', { cmdline: line });
  };
  $('shell-cmd').onkeydown = (e) => {
    if (e.key === 'Enter') { $('btn-shell').click(); }
  };
  $('btn-shell-kill').onclick = () => cmd('shell.kill');

  $('btn-status').onclick = async () => {
    const r = await cmd('sys.status');
    if (!r || !r.ok) { return; }
    const d = r.data;
    const heaps = (d.heaps || [])
      .map((h) => '  ' + h.name.padEnd(18) + String(h.free).padStart(9) +
                  ' free / ' + h.total)
      .join('\n');
    $('sys-meta').textContent =
      'uptime ' + d.uptime + 's, ' + d.tasks + ' 个任务\n' + heaps;
  };

  $('btn-reboot').onclick = async () => {
    if (!confirm('重启开发板？TCP 会断开并自动重新引导。')) { return; }
    await cmd('sys.reboot');
    addLog('me', 'sys.reboot: 已应答，板子随后重启');
  };

  $('btn-cap-start').onclick = () => send({ op: 'capture', action: 'start' });
  $('btn-cap-stop').onclick = () => send({ op: 'capture', action: 'stop' });

  $('btn-log-sub').onclick = () => cmd('log.subscribe', { on: true })
    .then((r) => {
      if (r && r.ok) { addLog('me', 'log: 补发 ' + r.data.replayed + ' 行'); }
    });
  $('btn-log-unsub').onclick = () => cmd('log.subscribe', { on: false });
  $('btn-log-pause').onclick = (e) => {
    paused = !paused;
    e.target.textContent = paused ? '继续' : '暂停';
    if (!paused) { renderLog(); }
  };
  $('btn-log-clear').onclick = () => { logLines = []; renderLog(); };
  $('log-filter').oninput = (e) => { filterText = e.target.value; renderLog(); };

  /* Draggable log pane: reading a long self-test output wants most of the
   * screen for a moment, and a fixed split makes that impossible. */
  const dragger = $('dragger');
  let dragging = false;
  dragger.onmousedown = () => { dragging = true; document.body.style.userSelect = 'none'; };
  window.onmouseup = () => { dragging = false; document.body.style.userSelect = ''; };
  window.onmousemove = (e) => {
    if (!dragging) { return; }
    const h = Math.max(60, window.innerHeight - e.clientY);
    $('logpane').style.height = h + 'px';
  };
}

wire();
connect();

