static bool wt_writable(int fd, int timeout_ms)
{
  struct pollfd pfd;

  pfd.fd = fd;
  pfd.events = POLLOUT;
  pfd.revents = 0;

  return poll(&pfd, 1, timeout_ms) == 1 && (pfd.revents & POLLOUT) != 0;
}

