static int handle_command(const struct bk7258_mb_wire_message *message)
{
  struct ack_slot *slot;
  unsigned int rx_index;
  uint8_t channel = bk7258_mb_header_channel(message);
  uint8_t control = bk7258_mb_header_ctrl(message);
  uint8_t ack_flags = 0;
  uint8_t state = 0;
  int ret = -ENOSYS;

  g_stats.last_command_header = message->header;

  if ((control & BK7258_MB_CTRL_SYNC_TX) == 0)
    {
      slot = alloc_ack_slot();
      if (slot == NULL)
        {
          g_stats.deferred_command++;
          return -EAGAIN;
        }
    }
  else
    {
      slot = NULL;
    }

  if ((control & ~(BK7258_MB_CTRL_SYNC_TX | BK7258_MB_CTRL_RESET)) != 0 ||
      bk7258_mb_header_state(message) != 0 ||
      (channel & 0xf0u) != 0x40u)
    {
      g_stats.bad_header++;
      state = BK7258_MB_STATE_COM_FAIL;
    }
  else if ((rx_index = rx_channel_index(channel)) < MB_RX_CHANNEL_COUNT &&
           g_rx_callbacks[rx_index] != NULL)
    {
      ret = g_rx_callbacks[rx_index](message, &ack_flags,
                                      g_rx_args[rx_index]);
      if (ret == -EAGAIN)
        {
          if (slot != NULL)
            {
              slot->state = ACK_SLOT_FREE;
            }

          g_stats.deferred_command++;
          return -EAGAIN;
        }
      else if (ret < 0)
        {
          state = BK7258_MB_STATE_COM_FAIL;
        }
    }
  else if (channel == BK7258_MB_CHAN_PWC_RX && g_pwc_rx != NULL)
    {
      ret = g_pwc_rx(message);
      if (ret == -EAGAIN)
        {
          if (slot != NULL)
            {
              slot->state = ACK_SLOT_FREE;
            }

          g_stats.deferred_command++;
          return -EAGAIN;
        }
      else if (ret < 0)
        {
          state = BK7258_MB_STATE_COM_FAIL;
        }
    }
  else if (channel == BK7258_MB_CHAN_SARADC_RX &&
           (bk7258_mb_header_cmd(message) == 0u ||
            bk7258_mb_header_cmd(message) == 1u) &&
           message->payload_address == 1u &&
           message->payload_length == 0u && message->flags == 0u &&
           message->crc8 == 0u && message->reserved == 0u)
    {
      /* Match Armino's SARADC operation-notification ABI. */
      ack_flags = 2u;
      ret = OK;
    }
  else
    {
      g_stats.unsupported++;
      state = BK7258_MB_STATE_COM_FAIL;
    }

  /* Socket channels need an explicit "handled and complete" state; see
   * BK7258_MB_STATE_ACK_COMPLETE.
   */

  if (channel == BK7258_MB_CHAN_IPC_RX && ret == OK && state == 0)
    {
      state = BK7258_MB_STATE_ACK_COMPLETE;
    }

  if ((control & BK7258_MB_CTRL_SYNC_TX) != 0)
    {
      return OK;
    }

  memset(&slot->message, 0, sizeof(slot->message));
  slot->message.header = bk7258_mb_make_header(
    bk7258_mb_header_cmd(message), state, BK7258_MB_CTRL_ACK_BOX,
    bk7258_mb_header_seq(message), channel);
  /* On the socket channels the peer reinterprets the whole ack box as the
   * command it sent -- ipc_router_tx_cmpl_isr() in the CP's mb_ipc.c does a
   * plain cast, `ipc_cmd = (mb_ipc_cmd_t *)ack_buf`, and then checks that
   * param1 still matches what it queued (masked with IPC_PARAM1_MASK,
   * 0x00FFFFFF).  So param1 has to be echoed, not replaced by our ack flags.
   *
   * Sending our own value instead made that check fail as "tx2 error @440!
   * 150 != 0": the CP had queued 0x150 and got back 0.  A failed check makes
   * the CP drop the frame without dequeuing it, and the router then takes the
   * link down -- 200 ms after the request, every time.  That also destroys
   * the only way to watch this from the AP, since the console is tunnelled
   * over the same mailbox; the diagnosis had to come from the CP's own log
   * plus its sources.
   *
   * param2 (payload_length and crc8) is echoed for the same reason.  The CP
   * only compares it when built with DEBUG_MB_IPC, but echoing costs nothing
   * and keeps the ack a faithful copy.
   */

  if (channel == BK7258_MB_CHAN_IPC_RX)
    {
      slot->message.payload_address = message->payload_address;
      slot->message.payload_length = message->payload_length;
      slot->message.crc8 = message->crc8;
    }
  else
    {
      slot->message.payload_address = ack_flags;
    }

  /* ack_state as well, not just ack_data1.  mb_chnl_ack_t's third word is the
   * state field (its union names it ack_state), and that is the one the peer
   * tests -- this port's own heartbeat does the same when it checks an ack
   * (bk7258_ipc_heartbeat.c ipc_ack_result() reads ->reserved).  Leaving it
   * zero while answering a command made the CP's mb_ipc socket stay in
   * "receive in process" forever: every later request to its flash server
   * came back with route and api status both RX_BUSY (ack byte 0x52) and no
   * reply.  Callers that pass 0 are unaffected.
   */

  slot->message.reserved = ack_flags;

  if (ack_slots_used() >= MB_ACK_HIGH_WATER)
    {
      g_probe_requested = true;
    }

  (void)dispatch_locked();
  return OK;
}

static int mailbox_rx(const struct bk7258_mb_wire_message *message)
{
  irqstate_t flags;
  uint8_t control;

  flags = up_irq_save();
  g_stats.rx++;
  control = bk7258_mb_header_ctrl(message);

          crc = (crc >> 1) ^ (0xedb88320u & (~(crc & 1u) + 1u));
        }
    }

  return crc;
}

/* CRC-8 with polynomial 0x31, table-free.  mb_ipc puts this over the payload
 * in cmd_data_crc8 and the receiver checks it (mb_ipc.c:1985); sending zero
 * instead made the server drop every request, which looked like a timeout
 * rather than a rejection.  Same table as cal_crc8_0x31(), computed rather
 * than copied.
 */

static uint8_t flash_crc8(FAR const uint8_t *data, size_t len)
{
  uint8_t crc = 0x00;
  size_t i;
  int bit;

  for (i = 0; i < len; i++)
    {
      crc ^= data[i];

      for (bit = 0; bit < 8; bit++)
        {
          crc = (uint8_t)((crc & 0x80u) != 0 ?
                          ((crc << 1) ^ 0x31u) : (crc << 1));
        }
    }

  return crc;
}

static uint32_t flash_ipc_param1(uint8_t tag)
{
  uint32_t dst = IPC_FLASH_SERVER_PORT | (IPC_FLASH_SERVER_CPU << 6);
  uint32_t src = IPC_FLASH_CLIENT_PORT | (IPC_FLASH_CLIENT_CPU << 6);

  return dst | (src << 8) | ((uint32_t)tag << 16);
}

/****************************************************************************
 * Name: flash_ipc_rx
 *
 * Description:
 *   One frame arrived from the CP on the IPC channel.  Interrupt context:
 *   record what came in and wake the requester, nothing else.
 *
 ****************************************************************************/

static int flash_ipc_rx(FAR const struct bk7258_mb_wire_message *message,
                        FAR uint8_t *ack_flags, FAR void *arg)
{
  UNUSED(arg);

  /* Tell the peer its frame is handled and done (ACK_STATE_COMPLETE, the
   * value mailbox_channel.c puts in ack_data1).  Answering 0 leaves the
   * server's socket in "receive in process", and every later request comes
   * back rejected: measured as ack status 0x52, i.e. route RX_BUSY (5) and
   * api RX_BUSY (2) at once, with no reply frame at all.
   */

  if (ack_flags != NULL)
    {
      *ack_flags = 2u;
    }

  g_flash.rsp_cmd = bk7258_mb_header_cmd(message);
  g_flash.rsp_user_cmd = message->crc8;
  g_flash.rsp_status = (uint8_t)(message->payload_address >> 24);
  g_flash.rsp_len = message->payload_length;
  g_flash.rsp_buff = (FAR uint8_t *)(uintptr_t)message->reserved;

  nxsem_post(&g_flash.done);
  return OK;
}

/****************************************************************************
 * Name: flash_ipc_tx_done
 *
 * Description:
 *   Channel-level acknowledgement of our frame.  The vendor's router takes
 *   its tx_status from here (mb_ipc.c:962), so this is where a request that
 *   the peer's *router* rejected shows up -- as opposed to one its handler
 *   answered.  Recorded so a silent server can be told apart from a refused
 *   frame.
 *
 ****************************************************************************/

static void flash_ipc_tx_done(FAR const struct bk7258_mb_wire_message *ack,
                              int result, FAR void *arg)
{
  UNUSED(arg);

  g_flash.tx_result = result;
  g_flash.tx_ack_status = ack != NULL ?
                          (uint8_t)(ack->payload_address >> 24) : 0xffu;
  g_flash.tx_ack_state = ack != NULL ? bk7258_mb_header_state(ack) : 0xffu;
}

/****************************************************************************
 * Name: flash_peer_ptr_ok
 *
 * Description:
 *   Whether a pointer the server handed us is one this core may dereference.
 *
 *   Everything in the reply is a CP-side address: the descriptor arrives in
 *   the frame's reserved field, and the read payload arrives as a pointer
 *   inside that descriptor.  Both are written by the other core, so neither
 *   can be trusted; a bad one faults, and an AP fault is nearly invisible
 *   because arm_lowputc() goes out through the mailbox that is itself in
 *   trouble.  The observed symptom was a boot that reached the flash read and
 *   then simply never got to NSH, with nothing printed.
 *
 *   Only CP RAM and the SWAP window are legitimate: those are the two regions
 *   both cores map (bk7258_mbox.h).  A pointer to CP *flash* or to a
 *   peripheral alias would read as something, which is worse than failing.
 *
 ****************************************************************************/

static bool flash_peer_ptr_ok(FAR const void *ptr, size_t len)
{
  uintptr_t addr = (uintptr_t)ptr;

  if (addr == 0 || len == 0)
    {
      return false;
    }

  if (addr >= BK7258_CP_RAM_START && addr + len <= BK7258_CP_RAM_END)
    {
      return true;
    }

  if (addr >= BK7258_SWAP_BASE &&
      addr + len <= BK7258_SWAP_BASE + BK7258_SWAP_SIZE)
    {
      return true;
    }

  return false;
}

/****************************************************************************
 * Name: flash_ipc_xfer
 *
 * Description:
 *   Send one frame and wait for the single frame that answers it.  Returns
 *   OK, or -ETIMEDOUT if the CP said nothing in time, or -EREMOTEIO if it
 *   answered with a router or API error.
 *
 ****************************************************************************/

static int flash_ipc_xfer(uint8_t cmd, uint8_t user_cmd,
                          FAR void *data, uint16_t len,
                          unsigned int timeout_ms)
{
  struct bk7258_mb_wire_message message;
  int ret;

  memset(&message, 0, sizeof(message));
  message.header = cmd;
  message.payload_address = flash_ipc_param1(g_flash.tag++);
  message.payload_length = len;
  message.flags = (data != NULL && len > 0) ?
                  flash_crc8((FAR const uint8_t *)data, len) : 0;
  message.crc8 = user_cmd;                 /* param2 bits 24-31 */
  message.reserved = (uint32_t)(uintptr_t)data;

  /* Drain a stale post, if any: a previous timeout may have left one. */

  while (nxsem_trywait(&g_flash.done) == OK)
    {
    }

  g_flash.rsp_cmd = IPC_USER_CMD_NONE;

  g_flash.tx_result = -EINPROGRESS;
  g_flash.tx_ack_status = 0xffu;
  g_flash.tx_ack_state = 0xffu;

  ret = bk7258_mailbox_send_wire(BK7258_MB_CHAN_IPC_TX, &message,
                                 flash_ipc_tx_done, NULL);
  if (ret < 0)
    {
      return ret;
    }

  ret = nxsem_tickwait_uninterruptible(&g_flash.done,
                                       MSEC2TICK(timeout_ms));
  if (ret < 0)
    {
      printf("flash: no answer to cmd=%u user=%u len=%u "
             "(tx result=%d ack state=0x%02x status=0x%02x)\n",
             cmd, user_cmd, len, g_flash.tx_result,
             g_flash.tx_ack_state, g_flash.tx_ack_status);
      return -ETIMEDOUT;
    }

  if (g_flash.rsp_buff != NULL &&
      !flash_peer_ptr_ok(g_flash.rsp_buff, sizeof(struct flash_ipc_cmd_s)))
    {
      printf("flash: reply descriptor at %p is outside CP RAM "
             "0x%08x-0x%08x and SWAP 0x%08x+0x%x; not dereferencing it\n",
             g_flash.rsp_buff,
             (unsigned int)BK7258_CP_RAM_START,
             (unsigned int)BK7258_CP_RAM_END,
             (unsigned int)BK7258_SWAP_BASE,
             (unsigned int)BK7258_SWAP_SIZE);
      return -EFAULT;
    }

  if (g_flash.rsp_status != 0)
    {
      return -EREMOTEIO;
    }

  return OK;
}

/****************************************************************************
 * Name: flash_notify_rx
 *
 * Description:
 *   The CP announces every flash access it is about to make, and its end, on
 *   MB_CHNL_FLASH -- for its own writes as much as for ours.  It then spins
 *   waiting for an acknowledgement whose ack_data1 reads IPC_FLASH_OP_ACK,
 *   giving up after 5ms (FLASH_WAIT_ACK_TIMEOUT in its flash_notify.c).  With
 *   this channel unregistered the transport answered COM_FAIL instead, so the
 *   CP burned that 5ms twice around every flash operation and nothing on this
 *   side ever learned that the part was busy.
 *
 *   Interrupt context.  Whatever a subscriber does here has to be ISR-safe and
 *   short: the CP is spinning on the answer.
 *
 ****************************************************************************/

static int flash_notify_rx(FAR const struct bk7258_mb_wire_message *message,
                           FAR uint8_t *ack_flags, FAR void *arg)
{
  uint8_t edge = bk7258_mb_header_cmd(message);

  UNUSED(arg);

  /* The vendor's handler answers unconditionally, before looking at anything;
   * an unanswered notification costs the CP 5ms whatever we think of it.
   */

  if (ack_flags != NULL)
    {
      *ack_flags = FLASH_OP_STATE_ACK;
    }

  if (message->payload_address != FLASH_OP_STATE_REQ)
    {
      return OK;
    }

  if (g_flash_op_notify != NULL &&
      (edge == FLASH_OP_START || edge == FLASH_OP_END))
    {
      g_flash_op_notify(edge == FLASH_OP_START, g_flash_op_notify_arg);
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int bk7258_flash_notify_init(void)
{
  return bk7258_mailbox_register_rx(BK7258_MB_CHAN_FLASH_RX,
                                    flash_notify_rx, NULL);
}

void bk7258_flash_op_notify_register(bk7258_flash_op_notify_t callback,
                                     FAR void *arg)
{
  g_flash_op_notify_arg = arg;
  g_flash_op_notify = callback;
}

int bk7258_flash_client_init(void)
{
  int ret;

  if (g_flash.connected)
    {
      return OK;
    }

  nxsem_init(&g_flash.done, 0, 0);

  ret = bk7258_mailbox_register_rx(BK7258_MB_CHAN_IPC_RX, flash_ipc_rx,
                                   NULL);
  if (ret < 0)
    {
      printf("flash: cannot take the IPC channel: %d\n", ret);
      return ret;
    }

  ret = flash_ipc_xfer(IPC_CMD_CONNECT, IPC_USER_CMD_NONE, NULL, 0,
                       FLASH_CONNECT_TIMEOUT_MS);
  if (ret < 0)
    {
      printf("flash: no answer from the CP flash server: %d\n", ret);
      return ret;
    }

  if ((g_flash.rsp_cmd & IPC_CMD_MASK) != IPC_CMD_CONNECT ||
      (g_flash.rsp_cmd & IPC_RSP_FLAG) == 0)
    {
      printf("flash: unexpected answer to connect: cmd=0x%02x\n",
             g_flash.rsp_cmd);
      return -EPROTO;
    }

  g_flash.connected = true;
  printf("flash: connected to the CP flash server (cpu%u port%u)\n",
         IPC_FLASH_SERVER_CPU, IPC_FLASH_SERVER_PORT);
  return OK;
}

bool bk7258_flash_client_ready(void)
{
  return g_flash.connected;
}

int bk7258_flash_read(uint32_t address, FAR void *buffer, size_t len)
{
  FAR uint8_t *out = buffer;
  int ret = OK;

  if (!g_flash.connected || buffer == NULL || len == 0)
    {
      return -EINVAL;
    }

  nxmutex_lock(&g_flash.lock);

  while (len > 0)
    {
      size_t chunk = len > FLASH_IPC_CHUNK ? FLASH_IPC_CHUNK : len;

      memset((FAR void *)flash_request, 0, sizeof(struct flash_ipc_cmd_s));
      (*flash_request).part_addr = flash_part_addr(address, 0);
      (*flash_request).len = (uint16_t)chunk;

      ret = flash_ipc_xfer(IPC_CMD_SEND, FLASH_CMD_READ, (FAR void *)flash_request,
                           sizeof(struct flash_ipc_cmd_s), FLASH_OP_TIMEOUT_MS);
      if (ret < 0)
        {
          break;
        }

      if (g_flash.rsp_user_cmd != FLASH_CMD_READ ||
          g_flash.rsp_len != sizeof(struct flash_ipc_cmd_s) ||
          g_flash.rsp_buff == NULL)
        {
          ret = -EPROTO;
          break;
        }

      {
        FAR const struct flash_ipc_cmd_s *rsp =
          (FAR const struct flash_ipc_cmd_s *)g_flash.rsp_buff;

        if (rsp->ret_status != 0 || rsp->len != chunk || rsp->buff == NULL)
          {
            ret = -EIO;
            break;
          }

        if (!flash_peer_ptr_ok(rsp->buff, chunk))
          {
            printf("flash: read payload at %p (%u bytes) is outside the "
                   "regions this core maps; refusing the copy\n",
                   rsp->buff, (unsigned int)chunk);
            ret = -EFAULT;
            break;
          }

        memcpy(out, rsp->buff, chunk);

        if (flash_payload_crc32(out, chunk) != rsp->crc)
          {
            ret = -EBADMSG;
            break;
          }
      }

      /* The server waits for this before releasing its buffer, and for one
       * receive per send of its own -- see flash_client.c's read path.
       */

      (void)flash_ipc_xfer(IPC_CMD_SEND, FLASH_CMD_READ_DONE,
                           (FAR void *)flash_request, sizeof(struct flash_ipc_cmd_s),
                           FLASH_OP_TIMEOUT_MS);

      out += chunk;
      address += chunk;
      len -= chunk;
    }

  nxmutex_unlock(&g_flash.lock);
  return ret;
}
#define BK7258_MB_HEADER_SEQ_SHIFT  16u
#define BK7258_MB_HEADER_SEQ_MASK   (0xffu << BK7258_MB_HEADER_SEQ_SHIFT)
#define BK7258_MB_HEADER_CHAN_SHIFT 24u
#define BK7258_MB_HEADER_CHAN_MASK  (0xffu << BK7258_MB_HEADER_CHAN_SHIFT)

_Static_assert((BK7258_MB_HEADER_CMD_MASK |
                BK7258_MB_HEADER_STATE_MASK |
                BK7258_MB_HEADER_CTRL_MASK |
                BK7258_MB_HEADER_SEQ_MASK |
                BK7258_MB_HEADER_CHAN_MASK) == UINT32_MAX,
               "mailbox header masks must cover exactly 32 bits");
_Static_assert((BK7258_MB_HEADER_STATE_MASK &
                BK7258_MB_HEADER_CTRL_MASK) == 0 &&
               (BK7258_MB_HEADER_SEQ_MASK &
                BK7258_MB_HEADER_CHAN_MASK) == 0,
               "mailbox header masks overlap");

#define BK7258_MB_CTRL_ACK_BOX      0x01u
#define BK7258_MB_CTRL_SYNC_TX      0x02u
#define BK7258_MB_CTRL_RESET        0x04u
#define BK7258_MB_STATE_COM_FAIL    0x01u

/* Armino's ACK_STATE_COMPLETE.  The mb_ipc socket layer only treats a command
 * as delivered when the acknowledgement says this; a state of zero leaves its
 * socket in "receive in process" and it then rejects everything else with
 * RX_BUSY.  Notification-only channels (BT, Wi-Fi, SARADC) do not look at it,
 * which is why they worked with zero.
 */

#define BK7258_MB_STATE_ACK_COMPLETE 0x02u

#define BK7258_MB_CHAN_HW_CTRL_TX   0x10u

/* mb_ipc's socket router.  Index 1 in the vendor's channel enum
 * (include/driver/mailbox_channel.h: MB_CHNL_HW_CTRL, CP0_MB_CHNL_IPC,
 * MB_CHNL_PWC, ...), which is what the CP's flash server listens on.
 */

#define BK7258_MB_CHAN_IPC_TX       0x11u
#define BK7258_MB_CHAN_PWC_TX       0x12u
#define BK7258_MB_CHAN_BT_TX        0x13u
#define BK7258_MB_CHAN_WIFI_CMD_TX  0x14u
#define BK7258_MB_CHAN_WIFI_DATA_TX 0x15u
#define BK7258_MB_CHAN_UART0_TX     0x19u

/* The flash operation notification, index 11 in the same enum
 * (MB_CHNL_FLASH).  The CP raises it before and after every flash access it
 * performs -- cp/middleware/driver/flash/flash_notify.c send_flash_op_state()
 * -- and then spins for up to 5ms waiting for an acknowledgement whose
 * ack_data1 reads IPC_FLASH_OP_ACK.  Only the RX direction is used here: the
 * CP is always the one that announces, this core only answers.
 */

#define BK7258_MB_CHAN_FLASH_TX     0x1bu
#define BK7258_MB_CHAN_IPC_RX       0x41u
#define BK7258_MB_CHAN_PWC_RX       0x42u
#define BK7258_MB_CHAN_BT_RX        0x43u
#define BK7258_MB_CHAN_WIFI_CMD_RX  0x44u
#define BK7258_MB_CHAN_WIFI_DATA_RX 0x45u
#define BK7258_MB_CHAN_UART0_RX     0x49u
#define BK7258_MB_CHAN_FLASH_RX     0x4bu
#define BK7258_MB_CHAN_SARADC_RX    0x4cu

#define BK7258_MB_UART_DATA         0u
#define BK7258_MB_UART_STATE        1u
#define BK7258_MB_UART_CHUNK_SIZE   128u

/* These values are generated by the app_ab RAM layout.  The linker script
 * independently asserts the complete SWAP reservation.
 */

#define BK7258_CP_RAM_START         0x28064000u
#define BK7258_CP_RAM_END           0x2809f700u
#define BK7258_SWAP_BASE            0x2809f800u
#define BK7258_SWAP_SIZE            0x00000800u
#define BK7258_IPC_TX_ADDRESS       0x2809f900u
#define BK7258_IPC_TX_SIZE          0x00000080u
/* The flash service's 16-byte descriptor.  It has to live in SWAP, not in the
 * AP's own RAM: the frame only carries a pointer, and the CP has to be able to
 * read what it points at.  A descriptor in AP RAM produced no answer at all
 * from the server -- the request was accepted by the router and then silently
 * dropped.
 */

#define BK7258_FLASH_IPC_ADDRESS    0x2809f980u
#define BK7258_FLASH_IPC_SIZE       0x00000020u

/* Payload staging for the flash service, one protocol chunk (512 bytes, the
 * FLASH_IPC_READ_SIZE/FLASH_IPC_WRITE_SIZE the vendor's flash_ipc.h fixes).
 *
 * A write frame carries only a pointer, and the CP dereferences it directly
 * (flash_server.c flash_write_handler() memcpy's from cmd_buff->buff and then
 * re-computes the CRC over it).  A pointer into the AP's own heap is no good:
 * the descriptor itself had to be moved here for exactly that reason -- see
 * BK7258_FLASH_IPC_ADDRESS -- so the bytes it points at have to be here too.
 */

#define BK7258_FLASH_DATA_ADDRESS   0x2809fa00u
#define BK7258_FLASH_DATA_SIZE      0x00000200u

#define BK7258_MB_UART_RX_ADDRESS   0x2809fc00u
#define BK7258_MB_UART_TX_ADDRESS   0x2809fd00u
#define BK7258_MB_SHARED_TX_START   BK7258_IPC_TX_ADDRESS
#define BK7258_MB_SHARED_TX_SIZE    \
  (BK7258_MB_UART_TX_ADDRESS + BK7258_MB_UART_CHUNK_SIZE - \
   BK7258_MB_SHARED_TX_START)

/* The contiguous run of SWAP this core writes and the CP reads: the IPC TX
 * frame, then the flash descriptor, then the flash payload staging buffer,
 * ending where the read-only UART RX window begins.  bk7258_start.c maps this
 * as one MPU region, which is what keeps it non-cacheable -- without a region
 * the addresses only work by falling back to the default memory map, and that
 * map calls this range cacheable.
 */

#define BK7258_MB_SHARED_RW_START   BK7258_IPC_TX_ADDRESS
#define BK7258_MB_SHARED_RW_SIZE    \
  (BK7258_MB_UART_RX_ADDRESS - BK7258_MB_SHARED_RW_START)

_Static_assert(BK7258_IPC_TX_ADDRESS >= BK7258_SWAP_BASE &&
               BK7258_IPC_TX_ADDRESS + BK7258_IPC_TX_SIZE <=
               BK7258_SWAP_BASE + BK7258_SWAP_SIZE,
               "IPC TX buffer lies outside SWAP");
_Static_assert((BK7258_IPC_TX_ADDRESS & 31u) == 0,
               "IPC TX buffer must be cache-line aligned");
_Static_assert(BK7258_MB_SHARED_TX_START + BK7258_MB_SHARED_TX_SIZE <=
               BK7258_SWAP_BASE + BK7258_SWAP_SIZE,
               "mailbox shared TX window lies outside SWAP");
_Static_assert(BK7258_MB_UART_RX_ADDRESS >= BK7258_SWAP_BASE &&
               BK7258_MB_UART_RX_ADDRESS + BK7258_MB_UART_CHUNK_SIZE <=
               BK7258_SWAP_BASE + BK7258_SWAP_SIZE,
               "mailbox UART RX lies outside SWAP");
_Static_assert(BK7258_MB_UART_TX_ADDRESS >= BK7258_SWAP_BASE &&
               BK7258_MB_UART_TX_ADDRESS + BK7258_MB_UART_CHUNK_SIZE <=
               BK7258_SWAP_BASE + BK7258_SWAP_SIZE,
               "mailbox UART TX lies outside SWAP");
_Static_assert((BK7258_MB_UART_RX_ADDRESS & 31u) == 0 &&
               (BK7258_MB_UART_TX_ADDRESS & 31u) == 0,
               "mailbox UART buffers must be cache-line aligned");
_Static_assert(BK7258_FLASH_IPC_ADDRESS >= BK7258_MB_SHARED_RW_START &&
               BK7258_FLASH_IPC_ADDRESS + BK7258_FLASH_IPC_SIZE <=
               BK7258_MB_SHARED_RW_START + BK7258_MB_SHARED_RW_SIZE,
               "flash descriptor lies outside the shared RW window");
_Static_assert(BK7258_FLASH_DATA_ADDRESS >= BK7258_MB_SHARED_RW_START &&
               BK7258_FLASH_DATA_ADDRESS + BK7258_FLASH_DATA_SIZE <=
               BK7258_MB_SHARED_RW_START + BK7258_MB_SHARED_RW_SIZE,
               "flash payload staging lies outside the shared RW window");
_Static_assert(BK7258_FLASH_IPC_ADDRESS >=
               BK7258_IPC_TX_ADDRESS + BK7258_IPC_TX_SIZE &&
               BK7258_FLASH_DATA_ADDRESS >=
               BK7258_FLASH_IPC_ADDRESS + BK7258_FLASH_IPC_SIZE,
               "flash windows overlap the IPC TX frame or each other");
_Static_assert((BK7258_FLASH_IPC_ADDRESS & 31u) == 0 &&
               (BK7258_FLASH_DATA_ADDRESS & 31u) == 0,
               "flash windows must be cache-line aligned");
_Static_assert(BK7258_MB_SHARED_RW_START >= BK7258_SWAP_BASE &&
               BK7258_MB_SHARED_RW_START + BK7258_MB_SHARED_RW_SIZE <=
               BK7258_SWAP_BASE + BK7258_SWAP_SIZE,
               "shared RW window lies outside SWAP");

struct bk7258_mb_wire_message
{
  uint32_t header;
  uint32_t payload_address;
  uint16_t payload_length;
  uint8_t flags;
  uint8_t crc8;
  uint32_t reserved;
};

_Static_assert(sizeof(struct bk7258_mb_wire_message) ==
               BK7258_MB_MESSAGE_SIZE, "mailbox message ABI size");
_Static_assert(offsetof(struct bk7258_mb_wire_message, header) == 0,
               "mailbox header ABI offset");
_Static_assert(offsetof(struct bk7258_mb_wire_message, payload_address) == 4,
               "mailbox payload ABI offset");
_Static_assert(offsetof(struct bk7258_mb_wire_message, payload_length) == 8,
               "mailbox length ABI offset");
_Static_assert(offsetof(struct bk7258_mb_wire_message, flags) == 10,
               "mailbox flags ABI offset");
_Static_assert(offsetof(struct bk7258_mb_wire_message, crc8) == 11,
               "mailbox CRC ABI offset");
_Static_assert(offsetof(struct bk7258_mb_wire_message, reserved) == 12,
               "mailbox reserved ABI offset");

static inline uint8_t
bk7258_mb_header_cmd(const struct bk7258_mb_wire_message *message)
{
  return (message->header & BK7258_MB_HEADER_CMD_MASK) >>
         BK7258_MB_HEADER_CMD_SHIFT;
}

static inline uint8_t
bk7258_mb_header_state(const struct bk7258_mb_wire_message *message)
{
  return (message->header & BK7258_MB_HEADER_STATE_MASK) >>
         BK7258_MB_HEADER_STATE_SHIFT;
}

static inline uint8_t

	if(SELF_CPU == phy_chnl_idx)  // received from self.
	{
		s_mailbox_tx_ack_fault_mask |= 0x2;
		return;
	}


	if(phy_chnl_idx >= PHY_CHNL_NUM){
		s_mailbox_tx_ack_fault_mask |= 0x4;
		return;
	}

	phy_chnl_ptr = &phy_chnl_x_cb[phy_chnl_idx];
	phy_chnl_ptr->last_ack_header = ack_ptr->hdr.data;
	phy_chnl_ptr->last_ack_data1 = ack_ptr->data1;
	log_chnl_cb_x = (mb_log_chnl_cb_t *)(phy_chnl_log_chnl_list[phy_chnl_idx]);

	if(log_chnl_idx >= phy_chnl_log_chnl_num[phy_chnl_idx])
	{
		s_mailbox_tx_ack_fault_mask |= 0x8;
		return;
	}

	u32 claim_flags = mb_chnl_enter_critical();
	if (phy_chnl_ptr->tx_state != CHNL_STATE_BUSY ||
		(ack_ptr->hdr.ctrl != CHNL_CTRL_ACK_BOX) ||
		 (ack_ptr->hdr.state & ~CHNL_STATE_COM_FAIL) ||
		 (log_chnl != phy_chnl_ptr->tx_log_chnl) ||
		 (ack_ptr->hdr.tx_seq != phy_chnl_ptr->tx_seq) ||
		 (ack_ptr->hdr.cmd != phy_chnl_ptr->tx_hdr_cmd))
	{
		phy_chnl_ptr->rx_fault_cnt++;
		phy_chnl_ptr->rx_fault_cnt |= 0x40000000;
		mb_chnl_exit_critical(claim_flags);
		return;
	}
	phy_chnl_ptr->tx_state = CHNL_STATE_IDLE;
	phy_chnl_ptr->busy_since_ms = 0;
	mb_chnl_exit_critical(claim_flags);

	bk_mailbox_tx_complete((mailbox_endpoint_t)phy_chnl_idx);

	if(log_chnl_cb_x[log_chnl_idx].tx_cmpl_isr != NULL)
	{
		/* clear following header members. */
		ack_ptr->hdr.logical_chnl = 0;
		ack_ptr->hdr.tx_seq       = 0;
		ack_ptr->hdr.ctrl         = 0;

		/* hdr.state, hdr.cmd these 2 members keep untouched. */
		s_mailbox_tx_compl_cnt++;
		log_chnl_cb_x[log_chnl_idx].tx_cmpl_isr(log_chnl_cb_x[log_chnl_idx].isr_param, (mb_chnl_ack_t *)ack_ptr);
	} else {
		s_mailbox_tx_ack_fault_mask |= 0x100;
	}

	u32 int_mask = mb_chnl_enter_critical();
	if (phy_chnl_ptr->tx_state != CHNL_STATE_IDLE)
	{
		mb_chnl_exit_critical(int_mask);
		return;
	}
	for(log_chnl_idx = 0; log_chnl_idx < phy_chnl_log_chnl_num[phy_chnl_idx]; log_chnl_idx++)  /* priority descended search. */
	{
		if(log_chnl_cb_x[log_chnl_idx].tx_state != CHNL_STATE_IDLE)
			break;
	}

	if(log_chnl_idx >= phy_chnl_log_chnl_num[phy_chnl_idx])
	{
		mb_chnl_exit_critical(int_mask);
		return;
	}

	log_chnl = CPX_LOG_CHNL_START(SELF_CPU, phy_chnl_idx) + log_chnl_idx;

	/* About to dispatch the next pending tx on this physical channel:
	 * refresh the busy-watchdog timestamp so its lifetime starts from
	 * here rather than carrying over from the previous transaction. */
	phy_chnl_ptr->tx_state = CHNL_STATE_BUSY;
	phy_chnl_ptr->busy_since_ms = rtos_get_time();

	ret_code = mb_phy_chnl_tx_cmd(log_chnl);

	if(ret_code != BK_OK)
	{
		log_chnl_cb_x[log_chnl_idx].tx_state = CHNL_STATE_IDLE;
		phy_chnl_ptr->tx_state               = CHNL_STATE_IDLE;
		phy_chnl_ptr->busy_since_ms          = 0;
	}
	mb_chnl_exit_critical(int_mask);

	return;

}

static void mb_phy_chnl_rx_cmd_isr(mb_phy_chnl_cmd_t *cmd_ptr)
{
	phy_chnnl_hdr_t  chnl_hdr;
	u8			log_chnl = cmd_ptr->hdr.logical_chnl;

	u8		phy_chnl_idx;
	u8		log_chnl_idx;

	mb_phy_chnl_cb_t * phy_chnl_ptr;
	mb_log_chnl_cb_t * log_chnl_cb_x;

	phy_chnl_idx = GET_SRC_CPU_ID(log_chnl);   // = SRC_CPU_ID; from SRC_CPU.
	log_chnl_idx = GET_LOG_CHNL_ID(log_chnl);

	s_mailbox_rx_cnt++;

	if(SELF_CPU != GET_DST_CPU_ID(log_chnl))
		return;

	if(SELF_CPU == phy_chnl_idx)  // received from self.
		return;

	if(phy_chnl_idx >= PHY_CHNL_NUM)
		return;

	phy_chnl_ptr = &phy_chnl_x_cb[phy_chnl_idx];
	log_chnl_cb_x = (mb_log_chnl_cb_t *)(phy_chnl_log_chnl_list[phy_chnl_idx]);

	chnl_hdr.data = cmd_ptr->hdr.data;

	if(log_chnl_idx >= phy_chnl_log_chnl_num[phy_chnl_idx])
	{
		phy_chnl_ptr->rx_fault_cnt++;
		phy_chnl_ptr->rx_fault_cnt |= 0x80000000;

		return;
	}

	if(log_chnl_cb_x[log_chnl_idx].rx_status_isr != NULL)
	{
		/* clear all other hdr members except hdr.cmd. */
		cmd_ptr->hdr.logical_chnl = 0;
		cmd_ptr->hdr.tx_seq       = 0;
		cmd_ptr->hdr.ctrl         = 0;
		cmd_ptr->hdr.state        = 0;

		if (log_chnl_cb_x[log_chnl_idx].rx_status_isr(
			log_chnl_cb_x[log_chnl_idx].isr_param,
			(mb_chnl_cmd_t *)cmd_ptr) != BK_OK)
			chnl_hdr.state |= CHNL_STATE_COM_FAIL;
	}
	else if(log_chnl_cb_x[log_chnl_idx].rx_isr != NULL)
	{
		/* clear all other hdr members except hdr.cmd. */
		cmd_ptr->hdr.logical_chnl = 0;
		cmd_ptr->hdr.tx_seq       = 0;
		cmd_ptr->hdr.ctrl         = 0;
		cmd_ptr->hdr.state        = 0;

		log_chnl_cb_x[log_chnl_idx].rx_isr(log_chnl_cb_x[log_chnl_idx].isr_param, (mb_chnl_cmd_t *)cmd_ptr);

		/* !!!! cmd_ptr buffer now contains ACK data !!!!. */
	}
	else
	{
		memset(cmd_ptr, 0, sizeof(*cmd_ptr));
		cmd_ptr->hdr.data = chnl_hdr.data;
		chnl_hdr.state |= CHNL_STATE_COM_FAIL;		/* cmd NO target app, it is an ACK bit to peer CPU. */
	}

	if(chnl_hdr.ctrl & CHNL_CTRL_SYNC_TX)
	{
		/* sync tx cmd, do NOT send ACK. */
		return;
	}

	/* RE-USE the copied command buffer to construct the stable ACK. */
	cmd_ptr->hdr.data  = chnl_hdr.data;
	cmd_ptr->hdr.ctrl |= CHNL_CTRL_ACK_BOX;			/* ACK msg, use the ACK channel.  */

	if (!mb_chnl_ack_enqueue(phy_chnl_idx, (mailbox_data_t *)cmd_ptr))
	{
		phy_chnl_ptr->tx_fault_cnt++;
		phy_chnl_ptr->tx_fault_cnt |= 0x80000000;
		return;
	}
	return;
}

static void mb_phy_chnl_rx_isr(mailbox_data_t * mb_data)
{
	mb_phy_chnl_union_t	rx_data;

	rx_data.mb_data.param0 = mb_data->param0;
	rx_data.mb_data.param1 = mb_data->param1;
	rx_data.mb_data.param2 = mb_data->param2;
	rx_data.mb_data.param3 = mb_data->param3;
	/* the following process will damage the input parameter,
	so pass in the pointer of copied parameter instad of the original. */

