/****************************************************************************
 * Secret-key classification used by the kvdb CLI.
 ****************************************************************************/

#include <stdio.h>

#include "../../../../app/kvdb_tool/kvdb_secret.h"

static int checks;
static int failures;

#define CHECK(cond, text)                    \
  do                                         \
    {                                        \
      checks++;                              \
      if (!(cond))                           \
        {                                    \
          failures++;                        \
          printf("  FAIL %s\n", text);      \
        }                                    \
    }                                        \
  while (0)

int main(void)
{
  CHECK(kvdb_key_is_secret("llm.key"), ".key is secret");
  CHECK(kvdb_key_is_secret("wifi.psk"), ".psk is secret");
  CHECK(kvdb_key_is_secret("web.token"), ".token is secret");
  CHECK(!kvdb_key_is_secret("web.host"), "host is not secret");
  CHECK(!kvdb_key_is_secret("tokenizer"), "only a token suffix is secret");
  CHECK(!kvdb_key_is_secret("monkey"), "key substring is not a suffix");

  printf("%d checks, %d failure(s)\n", checks, failures);
  return failures == 0 ? 0 : 1;
}

/****************************************************************************
 * Secret-key classification shared by the kvdb CLI and host tests.
 ****************************************************************************/

#ifndef __APP_KVDB_TOOL_KVDB_SECRET_H
#define __APP_KVDB_TOOL_KVDB_SECRET_H

#include <stdbool.h>
#include <stddef.h>
#include <string.h>

static inline bool kvdb_key_has_suffix(const char *key, const char *suffix)
{
  size_t key_len = strlen(key);
  size_t suffix_len = strlen(suffix);

  return key_len >= suffix_len &&
         strcmp(key + key_len - suffix_len, suffix) == 0;
}

static inline bool kvdb_key_is_secret(const char *key)
{
  return kvdb_key_has_suffix(key, ".key") ||
         kvdb_key_has_suffix(key, ".psk") ||
         kvdb_key_has_suffix(key, ".token");
}

#endif

