#include <stdint.h>
#include <string.h>
#include "bk7258_jpeg_enc.h"
int main(int argc, char **argv) {
  int ai;
  for (ai=1; ai<argc; ai++) {
    FILE *f=fopen(argv[ai],"rb"); long n; uint8_t *b; size_t s,e,end,len; int r;
    if (!f) return 2; fseek(f,0,SEEK_END); n=ftell(f); rewind(f);
    b=malloc((size_t)n*3u); if (!b) return 2;
    if (fread(b,1,(size_t)n,f)!=(size_t)n) return 2; fclose(f);
    s=0; while (s+3u<(size_t)n && !(b[s]==0xff && b[s+1]==0xda)) s++;
    e=s+2u+((size_t)b[s+2]<<8)+b[s+3]; end=(size_t)n-2u; len=end-e;
    r=bk7258_jpeg_realign_entropy(b+e,&len,(size_t)n*3u-e,640,480);
    printf("%s shift=%d len=%zu\n",argv[ai],r,len); free(b);
  }
  return 0;
}

