             "elapsed=%ums measured=%u.%02u fps\n",
             (unsigned int)priv->frames_done,
             (unsigned int)priv->timeouts, (unsigned int)ms,
             (unsigned int)(ms ? priv->frames_done * 1000u / ms : 0u),
             (unsigned int)(ms ? priv->frames_done * 100000u / ms % 100u
                               : 0u));

      if (priv->jpeg)
        {
