/****************************************************************************
 * Name: bk7258_jpeg_sw_encode
 *
 * Description:
 *   Encode one frame.  Returns the encoded length, or a negated errno.
 *
 *   Public, and deliberately free of this driver's device context, because
 *   the capture path needs the same encoder: the hardware JPEG block on
 *   /dev/video0 mis-assembles its bitstream (see the capture driver), so
 *   camera-to-JPEG is served by capturing UYVY and encoding it here.  Both
 *   users pass their own geometry, quality and de-interleave scratch.
 *
 *   Runs for a long time by driver standards -- 252 to 286ms for 640x480 at
 *   quality 80, measured -- so callers must be in a thread, never in an
 *   interrupt handler.
 *
 ****************************************************************************/

int bk7258_jpeg_sw_encode(FAR const struct bk7258_jpeg_sw_req_s *req)
{
  struct jpeg_compress_struct cinfo;
  struct jpeg_error_mgr jerr;
  struct bk7258_jpeg_planes_s planes;
  JSAMPROW yrows[2 * DCTSIZE];
  JSAMPROW crows[2 * DCTSIZE];
  JSAMPROW vrows[2 * DCTSIZE];
  JSAMPARRAY data[3];
  FAR uint8_t *src = req->src;
  size_t srclen = req->srclen;
  FAR uint8_t *dst = req->dst;
  size_t dstlen = req->dstlen;
  uint32_t width = req->width;
  uint32_t height = req->height;
  uint32_t format = req->pixelformat;
  unsigned long outlen;
  uint8_t *outptr = dst;
  int mcu_rows;
  int i;

  if (srclen < bk7258_jpeg_raw_size(format, width, height))
    {
      return -EINVAL;
    }

  switch (format)
    {
      case V4L2_PIX_FMT_YUV420:
        bk7258_jpeg_describe_i420(&planes, src, width, height);
        break;
  req.dst          = dst;
  req.dstlen       = dstlen;
  req.scratch      = g_sw_scratch;
  req.scratch_size = g_sw_scratch_size;
  req.width        = width;
  req.height       = height;
  req.pixelformat  = V4L2_PIX_FMT_VYUY;
  req.quality      = CONFIG_BK7258_JPEG_ENC_QUALITY;

  return bk7258_jpeg_sw_encode(&req);
}

/****************************************************************************
 * Name: bk7258_jpeg_enc_initialize
 ****************************************************************************/

int bk7258_jpeg_enc_initialize(void)
{
  int ret;

  ret = codec_register(CONFIG_BK7258_JPEG_ENC_DEV_PATH,
                       &g_bk7258_jpeg_codec);
  if (ret < 0)
    {
      printf("bk7258_jpeg: failed to register %s: %d\n",
             CONFIG_BK7258_JPEG_ENC_DEV_PATH, ret);
      return ret;
    }

  printf("bk7258_jpeg: %s registered (YUV420/UYVY -> JPEG, q=%d, "
         "buffers from PSRAM)\n",
         CONFIG_BK7258_JPEG_ENC_DEV_PATH, CONFIG_BK7258_JPEG_ENC_QUALITY);

  /* Serve /dev/video0's JPEG format from here too.  The hardware JPEG block
   * delivers at 30fps but mis-assembles its bitstream, so a camera-to-JPEG
   * capture comes back as parts of two frames; encoding a UYVY capture is
   * slower and correct.  See bk7258_camera_set_sw_jpeg().
   */

  /* /dev/video0's JPEG format is served from here unconditionally.
   *
   * The alternative -- letting the DVP feed the hardware JPEG block and
   * assembling the bitstream in the driver -- was measured on 2026-08-17 at
   * 11 bad frames out of 15: the block's own SOS sits behind a run of FF
   * fill whose length varies per frame, so the entropy start came out 16
   * bytes early and the leftover SOS bytes were decoded as picture (wrong
   * DC and chroma on a plausible-looking image).  The software encoder is
   * slower (about 290ms per 640x480 frame) and correct, so it is the only
   * path offered rather than a build-time choice that can be got wrong.
   */

  bk7258_camera_set_sw_jpeg(bk7258_camera_sw_jpeg_encode);

#ifdef CONFIG_BK7258_CAMERA_HW_JPEG
  printf("bk7258_jpeg: /dev/video0 JPEG uses hardware through 640px, "
         "software above 640px\n");
#else
  printf("bk7258_jpeg: /dev/video0 JPEG served by the software encoder\n");
#endif

  return 0;
}

  bk7258_jpeg_enc_soft_reset();
  bk7258_yuv_buf_soft_reset();

  bk7258_dma_stop_channel(BK7258_CAMERA_JPEG_DMA_CH);
  bk7258_camera_jpeg_dma_arm(priv);

  bk7258_yuv_buf_start_jpeg();
  bk7258_jpeg_enc_start();
}

/****************************************************************************
 * Name: bk7258_camera_set_sw_jpeg
 *
 * Description:
 *   Register the software JPEG encoder used to serve V4L2_PIX_FMT_JPEG on
 *   this capture device, or NULL to fall back to the hardware block.
 *
 *   Why a hook rather than a direct call: the encoder is libjpeg-turbo, which
 *   lives in the apps tree and is linked by the board layer
 *   (boards/.../src/bk7258_jpeg_enc.c).  Calling it from here would make this
 *   chip driver depend on both, inverting the direction every other file in
 *   this tree follows (board calls chip).  The board registers itself at
 *   bring-up instead.
 *
 *   Why software at all: the hardware JPEG block delivers at 30fps but
 *   mis-assembles its bitstream -- on a static scene consecutive frames came
 *   back differing by 50 to 140 grey levels, with each picture ending in
 *   another frame's data, while every marker check passed.  Encoding a UYVY
 *   capture instead is ~3.3fps but correct, and correctness is what
 *   /dev/video0's JPEG format is for (packages/ai_agent's camera_capture
 *   takes one photo).
 *
 ****************************************************************************/

static bk7258_camera_sw_jpeg_t g_sw_jpeg;

void bk7258_camera_set_sw_jpeg(bk7258_camera_sw_jpeg_t encoder)
{
  g_sw_jpeg = encoder;
}

/****************************************************************************
 * Name: bk7258_camera_sw_jpeg_work
 *
 * Description:
 *   Encode the staged raw frame into the application's buffer and complete
 *   it.  Work-queue context, so printf and long work are both allowed.
 *
 ****************************************************************************/
 * board/beken/chips/bk7258/include/bk7258_camera_imgdata.h
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

