/****************************************************************************
 * app/provisioning_web/vp_store.c
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include "vp_form.h"
#include "vp_store.h"

#define VP_OFF_MAGIC     0
#define VP_OFF_VERSION   4
#define VP_OFF_FLAGS     6
#define VP_OFF_GEN       8
#define VP_OFF_SSID_LEN  12
#define VP_OFF_PSK_LEN   13
#define VP_OFF_SSID      14
#define VP_OFF_PSK       46
#define VP_OFF_RESERVED  109
#define VP_OFF_CRC       110

#define VP_STORE_PATH_MAX 192

uint32_t vp_crc32(const void *data, size_t len)
{
  const unsigned char *p = (const unsigned char *)data;
  uint32_t crc = 0xffffffffu;
  size_t i;

  /* Bitwise rather than a table: 114 bytes twice per save is not worth 1KB of
   * flash on a part that is already at 90% of its region.
   */

  for (i = 0; i < len; i++)
    {
      unsigned bit;

      crc ^= p[i];
      for (bit = 0; bit < 8; bit++)
        {
          crc = (crc >> 1) ^ (0xedb88320u & (uint32_t)(-(int32_t)(crc & 1u)));
        }
    }

  return crc ^ 0xffffffffu;
}

static void vp_put16(uint8_t *buf, uint16_t value)
{
  buf[0] = (uint8_t)(value & 0xffu);
  buf[1] = (uint8_t)((value >> 8) & 0xffu);
}

static void vp_put32(uint8_t *buf, uint32_t value)
{
  buf[0] = (uint8_t)(value & 0xffu);
  buf[1] = (uint8_t)((value >> 8) & 0xffu);
  buf[2] = (uint8_t)((value >> 16) & 0xffu);
  buf[3] = (uint8_t)((value >> 24) & 0xffu);
}

static uint16_t vp_get16(const uint8_t *buf)
{
  return (uint16_t)((uint16_t)buf[0] | (uint16_t)((uint16_t)buf[1] << 8));
}

static uint32_t vp_get32(const uint8_t *buf)
{
  return (uint32_t)buf[0] | ((uint32_t)buf[1] << 8) |
         ((uint32_t)buf[2] << 16) | ((uint32_t)buf[3] << 24);
}

static size_t vp_len(const char *s, size_t maxlen)
{
  size_t n = 0;

  while (n < maxlen && s[n] != '\0')
    {
      n++;
    }

  return n;
}

int vp_record_encode(uint8_t *buf, size_t buflen,
                     const struct velasight_prov_credentials_s *cred)
{
  size_t ssid_len;
  size_t psk_len;
  int ret;

  if (buf == NULL || cred == NULL)
    {
      return -EINVAL;
    }

  if (buflen < VP_RECORD_SIZE)
    {
      return -E2BIG;
    }

  ret = vp_credentials_validate(cred);
  if (ret < 0)
    {
      return ret;
    }

  ssid_len = vp_len(cred->ssid, sizeof(cred->ssid));
  psk_len  = vp_len(cred->password, sizeof(cred->password));

  memset(buf, 0, VP_RECORD_SIZE);
  memcpy(buf + VP_OFF_MAGIC, VP_RECORD_MAGIC, 4);
  vp_put16(buf + VP_OFF_VERSION, VP_RECORD_VERSION);
  vp_put16(buf + VP_OFF_FLAGS,
           cred->open_network ? VP_RECORD_FLAG_OPEN : 0);
  vp_put32(buf + VP_OFF_GEN, cred->generation);
  buf[VP_OFF_SSID_LEN] = (uint8_t)ssid_len;
  buf[VP_OFF_PSK_LEN]  = (uint8_t)psk_len;
  memcpy(buf + VP_OFF_SSID, cred->ssid, ssid_len);
  memcpy(buf + VP_OFF_PSK, cred->password, psk_len);
  vp_put32(buf + VP_OFF_CRC, vp_crc32(buf, VP_RECORD_SIZE - 4));
  return VP_RECORD_SIZE;
}

static bool vp_padding_is_zero(const uint8_t *buf, size_t offset,
                               size_t used, size_t field)
{
  size_t i;

  for (i = used; i < field; i++)
    {
      if (buf[offset + i] != 0)
        {
          return false;
        }
    }

  return true;
}

int vp_record_decode(const uint8_t *buf, size_t len,
                     struct velasight_prov_credentials_s *cred)
{
  struct velasight_prov_credentials_s parsed;
  size_t ssid_len;
  size_t psk_len;
  uint16_t flags;

  if (buf == NULL || cred == NULL)
    {
      return -EINVAL;
    }

  /* Exactly one size is legal.  A shorter file is a truncated write and a
   * longer one is not this format, and neither is worth guessing about.
   */

  if (len != VP_RECORD_SIZE)
    {
      return -EBADMSG;
    }

  if (memcmp(buf + VP_OFF_MAGIC, VP_RECORD_MAGIC, 4) != 0 ||
      vp_get16(buf + VP_OFF_VERSION) != VP_RECORD_VERSION ||
      buf[VP_OFF_RESERVED] != 0)
    {
      return -EBADMSG;
    }

  if (vp_get32(buf + VP_OFF_CRC) != vp_crc32(buf, VP_RECORD_SIZE - 4))
    {
      return -EBADMSG;
    }

  flags    = vp_get16(buf + VP_OFF_FLAGS);
  ssid_len = buf[VP_OFF_SSID_LEN];
  psk_len  = buf[VP_OFF_PSK_LEN];

  if ((flags & ~(uint16_t)VP_RECORD_FLAG_OPEN) != 0)
    {
      return -EBADMSG;
    }

  if (ssid_len == 0 || ssid_len > VELASIGHT_PROV_SSID_MAX)
    {
      return -EBADMSG;
    }

  if (psk_len != 0 &&
      (psk_len < VELASIGHT_PROV_PSK_MIN || psk_len > VELASIGHT_PROV_PSK_MAX))
    {
      return -EBADMSG;
    }

  if (((flags & VP_RECORD_FLAG_OPEN) != 0) != (psk_len == 0))
    {
      return -EBADMSG;
    }

  if (!vp_padding_is_zero(buf, VP_OFF_SSID, ssid_len,
                          VELASIGHT_PROV_SSID_MAX) ||
      !vp_padding_is_zero(buf, VP_OFF_PSK, psk_len,
                          VELASIGHT_PROV_PSK_MAX))
    {
      return -EBADMSG;
    }

  memset(&parsed, 0, sizeof(parsed));
  memcpy(parsed.ssid, buf + VP_OFF_SSID, ssid_len);
  memcpy(parsed.password, buf + VP_OFF_PSK, psk_len);
  parsed.generation   = vp_get32(buf + VP_OFF_GEN);
  parsed.open_network = psk_len == 0;

  /* The record can be structurally perfect and still describe credentials the
   * running code would refuse, for instance after a limit changes.  Treat that
   * as corrupt rather than handing the caller something it cannot use.
   */

  if (vp_credentials_validate(&parsed) < 0)
    {
      return -EBADMSG;
    }

  *cred = parsed;
  return 0;
}

static int vp_make_parent(const char *path)
{
  char dir[VP_STORE_PATH_MAX];
  const char *slash;
  size_t len;

  slash = strrchr(path, '/');
  if (slash == NULL || slash == path)
    {
      return 0;
    }

  len = (size_t)(slash - path);
  if (len >= sizeof(dir))
    {
      return -ENAMETOOLONG;
    }

  memcpy(dir, path, len);
  dir[len] = '\0';

  if (mkdir(dir, 0777) == 0 || errno == EEXIST)
    {
      return 0;
    }

  return -errno;
}

int vp_store_save(const char *path,
                  const struct velasight_prov_credentials_s *cred)
{
  uint8_t record[VP_RECORD_SIZE];
  char tmp[VP_STORE_PATH_MAX + 8];
  FILE *stream;
  int ret;

  if (path == NULL || cred == NULL)
    {
      return -EINVAL;
    }

  if (strlen(path) >= VP_STORE_PATH_MAX)
    {
      return -ENAMETOOLONG;
    }

  ret = vp_record_encode(record, sizeof(record), cred);
  if (ret < 0)
    {
      return ret;
    }

  ret = vp_make_parent(path);
  if (ret < 0)
    {
      return ret;
    }

  snprintf(tmp, sizeof(tmp), "%s.tmp", path);

  stream = fopen(tmp, "wb");
  if (stream == NULL)
    {
      return -errno;
    }

  /* Write, flush, fsync, close, rename.  Without the fsync the rename can be
   * durable while the data behind it is not, which on a power cut leaves a
   * record that passes its own CRC check by accident or fails it for no
   * reason the next boot can explain.
   */

  if (fwrite(record, 1, sizeof(record), stream) != sizeof(record) ||
      fflush(stream) != 0 || fsync(fileno(stream)) != 0)
    {
      ret = errno != 0 ? -errno : -EIO;
      fclose(stream);
      unlink(tmp);
      return ret;
    }

  if (fclose(stream) != 0)
    {
      ret = errno != 0 ? -errno : -EIO;
      unlink(tmp);
      return ret;
    }

  if (rename(tmp, path) < 0)
    {
      ret = -errno;
      unlink(tmp);
      return ret;
    }

  sync();
  return 0;
}

int vp_store_load(const char *path,
                  struct velasight_prov_credentials_s *cred)
{
  uint8_t record[VP_RECORD_SIZE + 1];
  FILE *stream;
  size_t nread;

  if (path == NULL || cred == NULL)
    {
      return -EINVAL;
    }

  stream = fopen(path, "rb");
  if (stream == NULL)
    {
      return errno == ENOENT ? -ENOENT : -errno;
    }

  nread = fread(record, 1, sizeof(record), stream);
  fclose(stream);

  return vp_record_decode(record, nread, cred);
}

uint32_t vp_store_next_generation(const char *path)
{
  struct velasight_prov_credentials_s cred;

  if (vp_store_load(path, &cred) < 0 || cred.generation == UINT32_MAX)
    {
      return 1;
    }

  return cred.generation + 1;
}

/****************************************************************************
 * app/provisioning_web/vp_http.c
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <errno.h>
#include <stdio.h>
#include <string.h>

#include "vp_http.h"

#define VP_HTTP_BODY_BUILD 3072

static const char g_form_type[] = "application/x-www-form-urlencoded";

static const char *vp_reason(int status)
{
  switch (status)
    {
      case 200: return "OK";
      case 400: return "Bad Request";
      case 404: return "Not Found";
      case 405: return "Method Not Allowed";
      case 411: return "Length Required";
      case 413: return "Payload Too Large";
      case 415: return "Unsupported Media Type";
      case 431: return "Request Header Fields Too Large";
      case 500: return "Internal Server Error";
      default:  return "Error";
    }
}

static bool vp_ci_prefix(const char *line, size_t linelen, const char *name)
{
  size_t namelen = strlen(name);
  size_t i;

  if (linelen < namelen)
    {
      return false;
    }

  for (i = 0; i < namelen; i++)
    {
      char a = line[i];
      char b = name[i];

      if (a >= 'A' && a <= 'Z')
        {
          a = (char)(a - 'A' + 'a');
        }

      if (b >= 'A' && b <= 'Z')
        {
          b = (char)(b - 'A' + 'a');
        }

      if (a != b)
        {
          return false;
        }
    }

  return true;
}

static const char *vp_header_value(const char *line, size_t linelen,
                                   const char *name, size_t *valuelen)
{
  size_t namelen = strlen(name);
  size_t i;

  if (!vp_ci_prefix(line, linelen, name))
    {
      return NULL;
    }

  i = namelen;
  if (i >= linelen || line[i] != ':')
    {
      return NULL;
    }

  i++;
  while (i < linelen && (line[i] == ' ' || line[i] == '\t'))
    {
      i++;
    }

  *valuelen = linelen - i;
  return line + i;
}

static int vp_reject(struct vp_http_request_s *req, int status)
{
  req->action = VP_HTTP_ACTION_REJECT;
  req->status = status;
  return 0;
}

int vp_http_parse(const char *buf, size_t len,
                  struct vp_http_request_s *req)
{
  const char *end;
  const char *line;
  const char *sp1;
  const char *sp2;
  size_t linelen;
  size_t targetlen;
  size_t remaining;
  size_t headers_len;
  bool is_post;
  bool have_length = false;
  bool form_type = false;
  size_t content_length = 0;

  if (buf == NULL || req == NULL)
    {
      return -EINVAL;
    }

  memset(req, 0, sizeof(*req));
  req->status = 400;

  /* No CRLFCRLF yet means either "keep reading" or "this client is not going
   * to stop", and the cap is what tells them apart.
   */

  end = NULL;
  if (len >= 4)
    {
      size_t i;

      for (i = 0; i + 4 <= len; i++)
        {
          if (memcmp(buf + i, "\r\n\r\n", 4) == 0)
            {
              end = buf + i;
              break;
            }
        }
    }

  if (end == NULL)
    {
      if (len >= VP_HTTP_MAX_HEADERS)
        {
          return vp_reject(req, 431);
        }

      return -EAGAIN;
    }

  headers_len = (size_t)(end - buf) + 4;
  if (headers_len > VP_HTTP_MAX_HEADERS)
    {
      return vp_reject(req, 431);
    }

  req->header_len = headers_len;

  /* Request line */

  line = buf;
  {
    const char *crlf = memchr(buf, '\r', (size_t)(end - buf) + 1);

    if (crlf == NULL)
      {
        return vp_reject(req, 400);
      }

    linelen = (size_t)(crlf - buf);
  }

  sp1 = memchr(line, ' ', linelen);
  if (sp1 == NULL)
    {
      return vp_reject(req, 400);
    }

  remaining = linelen - (size_t)(sp1 + 1 - line);
  sp2 = memchr(sp1 + 1, ' ', remaining);
  targetlen = sp2 != NULL ? (size_t)(sp2 - (sp1 + 1)) : remaining;
  if (targetlen == 0)
    {
      return vp_reject(req, 400);
    }

  if ((size_t)(sp1 - line) == 3 && memcmp(line, "GET", 3) == 0)
    {
      is_post = false;
    }
  else if ((size_t)(sp1 - line) == 4 && memcmp(line, "POST", 4) == 0)
    {
      is_post = true;
    }
  else
    {
      return vp_reject(req, 405);
    }

  /* The query string is not used; stripping it keeps "/" and "/?x=1" from
   * being two different paths.
   */

  {
    const char *target = sp1 + 1;
    const char *query = memchr(target, '?', targetlen);
    size_t pathlen = query != NULL ? (size_t)(query - target) : targetlen;

    if (!is_post)
      {
        bool root = pathlen == 1 && target[0] == '/';
        bool index = pathlen == 11 &&
                     memcmp(target, "/index.html", 11) == 0;

        if (!root && !index)
          {
            return vp_reject(req, 404);
          }

        req->action = VP_HTTP_ACTION_PAGE;
        return 0;
      }

    if (pathlen != 5 || memcmp(target, "/save", 5) != 0)
      {
        return vp_reject(req, 404);
      }
  }

  /* Headers.  Only three matter, and anything unexpected about them is a
   * refusal rather than a default, because this listener has no authentication
   * standing between it and the air.
   */

  {
    const char *cursor = buf + linelen + 2;

    while (cursor < end)
      {
        const char *crlf = memchr(cursor, '\r', (size_t)(end - cursor) + 1);
        const char *value;
        size_t valuelen;
        size_t thislen;

        if (crlf == NULL)
          {
            break;
          }

        thislen = (size_t)(crlf - cursor);
        if (thislen == 0)
          {
            break;
          }

        if (vp_header_value(cursor, thislen, "transfer-encoding",
                            &valuelen) != NULL)
          {
            return vp_reject(req, 400);
          }

        value = vp_header_value(cursor, thislen, "content-type", &valuelen);
        if (value != NULL)
          {
            form_type = valuelen >= strlen(g_form_type) &&
                        vp_ci_prefix(value, valuelen, g_form_type);
          }

        value = vp_header_value(cursor, thislen, "content-length", &valuelen);
        if (value != NULL)
          {
            size_t i;

            have_length = true;
            content_length = 0;
            if (valuelen == 0)
              {
                return vp_reject(req, 400);
              }

            for (i = 0; i < valuelen; i++)
              {
                if (value[i] < '0' || value[i] > '9')
                  {
                    return vp_reject(req, 400);
                  }

                if (content_length > (VP_HTTP_MAX_BODY + 1) / 10 + 1)
                  {
                    return vp_reject(req, 413);
                  }

                content_length = content_length * 10 +
                                 (size_t)(value[i] - '0');
              }
          }

        cursor = crlf + 2;
      }
  }

  if (!form_type)
    {
      return vp_reject(req, 415);
    }

  if (!have_length)
    {
      return vp_reject(req, 411);
    }

  if (content_length > VP_HTTP_MAX_BODY)
    {
      return vp_reject(req, 413);
    }

  if (content_length == 0)
    {
      return vp_reject(req, 400);
    }

  req->action = VP_HTTP_ACTION_SAVE;
  req->status = 200;
  req->content_length = content_length;
  return 0;
}

int vp_html_escape(const char *in, char *out, size_t outlen)
{
  size_t o = 0;
  size_t i;

  if (in == NULL || out == NULL || outlen == 0)
    {
      return -EINVAL;
    }

  for (i = 0; in[i] != '\0'; i++)
    {
      const char *rep;

      switch (in[i])
        {
          case '&':  rep = "&amp;";  break;
          case '<':  rep = "&lt;";   break;
          case '>':  rep = "&gt;";   break;
          case '"':  rep = "&quot;"; break;
          case '\'': rep = "&#39;";  break;
          default:   rep = NULL;     break;
        }

      if (rep != NULL)
        {
          size_t replen = strlen(rep);

          if (o + replen + 1 > outlen)
            {
              return -E2BIG;
            }

          memcpy(out + o, rep, replen);
          o += replen;
        }
      else
        {
          if (o + 2 > outlen)
            {
              return -E2BIG;
            }

          out[o++] = in[i];
        }
    }

  out[o] = '\0';
  return (int)o;
}

static size_t vp_wrap(char *buf, size_t buflen, int status,
                      const char *body, size_t bodylen)
{
  int header;

  header = snprintf(buf, buflen,
                    "HTTP/1.1 %d %s\r\n"
                    "Content-Type: text/html; charset=utf-8\r\n"
                    "Content-Length: %u\r\n"
                    "Cache-Control: no-store\r\n"
                    "%s"
                    "Connection: close\r\n"
                    "\r\n",
                    status, vp_reason(status), (unsigned)bodylen,
                    status == 405 ? "Allow: GET, POST\r\n" : "");

  if (header < 0 || (size_t)header + bodylen + 1 > buflen)
    {
      return 0;
    }

  memcpy(buf + header, body, bodylen);
  buf[(size_t)header + bodylen] = '\0';
  return (size_t)header + bodylen;
}

/* One stylesheet, no scripts and no external references: the phone that opens
 * this page has no route to the internet yet, so anything not inlined would
 * simply be a broken link.
 */

#define VP_PAGE_HEAD                                                   \
  "<!DOCTYPE html><html lang=\"zh-CN\"><head>"                         \
  "<meta charset=\"utf-8\">"                                           \
  "<meta name=\"viewport\" content=\"width=device-width,"               \
  "initial-scale=1\">"                                                 \
  "<title>VelaSight 配网</title><style>"                                \
  "body{font-family:system-ui,sans-serif;margin:0;padding:24px;"        \
  "background:#f5f5f7;color:#1d1d1f}"                                   \
  "main{max-width:22rem;margin:0 auto;background:#fff;border-radius:"   \
  "12px;padding:20px}"                                                  \
  "h1{font-size:1.25rem;margin:0 0 16px}"                               \
  "label{display:block;margin:12px 0 4px;font-size:.9rem}"              \
  "input{width:100%;box-sizing:border-box;padding:10px;font-size:1rem;" \
  "border:1px solid #c7c7cc;border-radius:8px}"                         \
  "button{width:100%;margin-top:20px;padding:12px;font-size:1rem;"      \
  "border:0;border-radius:8px;background:#0071e3;color:#fff}"           \
  "p.note{font-size:.85rem;color:#6e6e73;margin-top:16px}"              \
  "p.err{color:#b00020;font-size:.9rem;margin:0 0 8px}"                 \
  "</style></head><body><main>"

#define VP_PAGE_TAIL "</main></body></html>"

size_t vp_http_form_page(char *buf, size_t buflen, const char *notice)
{
  char escaped[256];
  char body[VP_HTTP_BODY_BUILD];
  int bodylen;

  if (buf == NULL)
    {
      return 0;
    }

  escaped[0] = '\0';
  if (notice != NULL && vp_html_escape(notice, escaped, sizeof(escaped)) < 0)
    {
      escaped[0] = '\0';
    }

  bodylen = snprintf(body, sizeof(body),
                     VP_PAGE_HEAD
                     "<h1>连接 Wi-Fi</h1>"
                     "%s%s%s"
                     "<form action=\"/save\" method=\"post\">"
                     "<label for=\"ssid\">网络名称（SSID）</label>"
                     "<input id=\"ssid\" name=\"ssid\" type=\"text\" "
                     "maxlength=\"32\" autocapitalize=\"off\" required>"
                     "<label for=\"password\">密码（开放网络留空）</label>"
                     "<input id=\"password\" name=\"password\" "
                     "type=\"password\" maxlength=\"63\">"
                     "<button type=\"submit\">保存</button>"
                     "</form>"
                     "<p class=\"note\">凭据保存在设备的持久存储中，"
                     "本页面不会切换 Wi-Fi 模式。</p>"
                     VP_PAGE_TAIL,
                     escaped[0] != '\0' ? "<p class=\"err\">" : "",
                     escaped,
                     escaped[0] != '\0' ? "</p>" : "");

  if (bodylen < 0)
    {
      return 0;
    }

  return vp_wrap(buf, buflen, 200, body, (size_t)bodylen);
}

size_t vp_http_saved_page(char *buf, size_t buflen, const char *ssid,
                          uint32_t generation, bool open_network)
{
  char escaped[VELASIGHT_PROV_SSID_MAX * 6 + 1];
  char body[VP_HTTP_BODY_BUILD];
  int bodylen;

  if (buf == NULL || ssid == NULL)
    {
      return 0;
    }

  if (vp_html_escape(ssid, escaped, sizeof(escaped)) < 0)
    {
      return 0;
    }

  bodylen = snprintf(body, sizeof(body),
                     VP_PAGE_HEAD
                     "<h1>已保存</h1>"
                     "<p>网络：<strong>%s</strong></p>"
                     "<p>加密：%s</p>"
                     "<p>第 %u 次保存</p>"
                     "<p class=\"note\">凭据已写入设备持久存储。"
                     "切换回普通 Wi-Fi 模式由应用完成，此热点可能随之断开。"
                     "</p>"
                     VP_PAGE_TAIL,
                     escaped, open_network ? "开放网络" : "有密码",
                     (unsigned)generation);

  if (bodylen < 0)
    {
      return 0;
    }

  return vp_wrap(buf, buflen, 200, body, (size_t)bodylen);
}

size_t vp_http_status_page(char *buf, size_t buflen, int status,
                           const char *message)
{
  char escaped[256];
  char body[1024];
  int bodylen;

  if (buf == NULL)
    {
      return 0;
    }

  escaped[0] = '\0';
  if (message != NULL && vp_html_escape(message, escaped,
                                        sizeof(escaped)) < 0)
    {
      escaped[0] = '\0';
    }

  bodylen = snprintf(body, sizeof(body),
                     VP_PAGE_HEAD
                     "<h1>%d %s</h1><p>%s</p>"
                     "<p class=\"note\"><a href=\"/\">返回配网页面</a></p>"
                     VP_PAGE_TAIL,
                     status, vp_reason(status), escaped);

  if (bodylen < 0)
    {
      return 0;
    }

  return vp_wrap(buf, buflen, status, body, (size_t)bodylen);
}

/****************************************************************************
 * app/provisioning_web/vp_server.c
 *
 * The socket half of the provisioning entry.  Deliberately POSIX-only so the
 * accept loop, the ordering guarantee and one-shot mode can be exercised over
 * loopback on the host; the only thing left for the board is whether the
 * SoftAP and SD-NAND are actually there.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <arpa/inet.h>
#include <errno.h>
#include <netinet/in.h>
#include <poll.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

#include "velasight_provisioning.h"
#include "vp_form.h"
#include "vp_http.h"
#include "vp_store.h"

#define VP_STATE_IDLE     0
#define VP_STATE_RUNNING  1
#define VP_STATE_FINISHED 2  /* the thread returned, still needs a join */

#define VP_ACCEPT_POLL_MS  200
#define VP_REQUEST_TIMEOUT_MS 5000
#define VP_STORE_PATH_MAX  192
#define VP_THREAD_STACK    8192

struct vp_server_s
{
  int       listenfd;
  pthread_t thread;
  int       state;
  bool      stopping;
  bool      one_shot;
  char      store_path[VP_STORE_PATH_MAX];
  uint32_t  generation;
  velasight_prov_saved_cb_t on_saved;
  void     *cb_arg;
};

static struct vp_server_s g_server =
{
  .listenfd = -1,
  .state    = VP_STATE_IDLE,
};

static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;

/* Request and response buffers are static because only one connection is
 * served at a time and 6KB of thread stack on this part is not free.
 */

static char g_request[VP_HTTP_MAX_HEADERS + VP_HTTP_MAX_BODY + 1];
static char g_response[VP_HTTP_RESPONSE_MAX];

static int vp_write_all(int fd, const char *data, size_t len)
{
  size_t sent = 0;

  while (sent < len)
    {
      ssize_t n = write(fd, data + sent, len - sent);

      if (n < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          return -errno;
        }

      if (n == 0)
        {
          return -EPIPE;
        }

      sent += (size_t)n;
    }

  return 0;
}

/****************************************************************************
 * Name: vp_read_request
 *
 * Description:
 *   Read until the headers plus the declared body have arrived, the cap is
 *   reached or the deadline passes.  Returns the total length, or negative on
 *   error.  A client that opens a connection and says nothing costs one
 *   timeout, not the service.
 *
 ****************************************************************************/

static int vp_read_request(int fd, struct vp_http_request_s *req)
{
  size_t total = 0;
  int waited = 0;

  for (; ; )
    {
      struct pollfd pfd;
      ssize_t n;
      int ret;

      ret = vp_http_parse(g_request, total, req);
      if (ret == 0)
        {
          if (req->action != VP_HTTP_ACTION_SAVE ||
              total >= req->header_len + req->content_length)
            {
              return (int)total;
            }
        }
      else if (ret != -EAGAIN)
        {
          return ret;
        }

      if (total >= sizeof(g_request) - 1)
        {
          return -E2BIG;
        }

      pfd.fd = fd;
      pfd.events = POLLIN;
      pfd.revents = 0;
      ret = poll(&pfd, 1, VP_ACCEPT_POLL_MS);
      if (ret < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          return -errno;
        }

      if (ret == 0)
        {
          waited += VP_ACCEPT_POLL_MS;
          if (waited >= VP_REQUEST_TIMEOUT_MS)
            {
              return -ETIMEDOUT;
            }

          continue;
        }

      n = read(fd, g_request + total, sizeof(g_request) - 1 - total);
      if (n < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          return -errno;
        }

      if (n == 0)
        {
          /* Peer closed.  Whatever arrived is all there will be, so let the
           * parser decide between "incomplete" and "answerable".
           */

          if (vp_http_parse(g_request, total, req) == 0 &&
              (req->action != VP_HTTP_ACTION_SAVE ||
               total >= req->header_len + req->content_length))
            {
              return (int)total;
            }

          return -ECONNRESET;
        }

      total += (size_t)n;
    }
}

/****************************************************************************
 * Name: vp_handle
 *
 * Description:
 *   Serve one connection.  Sets *saved when credentials were persisted and
 *   *save_status to 0 or the negative errno of a failed save, so the caller can
 *   notify the application only after the socket is gone.
 *
 ****************************************************************************/

static void vp_handle(int fd, bool *saved, int *save_status,
                      uint32_t *generation)
{
  struct velasight_prov_credentials_s cred;
  struct vp_http_request_s req;
  size_t len = 0;
  int ret;

  *saved = false;
  *save_status = 0;

  ret = vp_read_request(fd, &req);
  if (ret < 0)
    {
      if (ret == -E2BIG)
        {
          len = vp_http_status_page(g_response, sizeof(g_response), 431,
                                    "请求过大。");
        }
      else
        {
          /* Nothing usable arrived; answering a client that already gave up
           * is not worth a second syscall.
           */

          return;
        }
    }
  else if (req.action == VP_HTTP_ACTION_PAGE)
    {
      len = vp_http_form_page(g_response, sizeof(g_response), NULL);
    }
  else if (req.action == VP_HTTP_ACTION_REJECT)
    {
      len = vp_http_status_page(g_response, sizeof(g_response), req.status,
                               req.status == 404 ? "页面不存在。" :
                               req.status == 405 ? "不支持该请求方法。" :
                               req.status == 413 ? "提交内容过大。" :
                               req.status == 415 ? "提交格式不受支持。" :
                               req.status == 411 ? "缺少 Content-Length。" :
                                                   "请求无法解析。");
    }
  else
    {
      memset(&cred, 0, sizeof(cred));
      ret = vp_form_parse(g_request + req.header_len, req.content_length,
                          &cred);
      if (ret < 0)
        {
          /* No detail about which field failed and no echo of what was typed:
           * the notice has to be useful to the person at the phone without
           * repeating a passphrase back over an open network.
           */

          len = vp_http_form_page(g_response, sizeof(g_response),
                                  "SSID 需 1-32 字节，密码需留空或 8-63 字节，"
                                  "请检查后重试。");
          if (len > 0)
            {
              /* Reuse the form page body but answer 400, so a client that
               * checks the status still learns the submit failed.
               */

              len = vp_http_status_page(g_response, sizeof(g_response), 400,
                                        "SSID 需 1-32 字节，密码需留空或 "
                                        "8-63 字节。");
            }
        }
      else
        {
          cred.generation = vp_store_next_generation(g_server.store_path);
          ret = vp_store_save(g_server.store_path, &cred);
          if (ret < 0)
            {
              *saved = false;
              *save_status = ret;
              len = vp_http_status_page(g_response, sizeof(g_response), 500,
                                        "写入持久存储失败，凭据未保存。");
            }
          else
            {
              *saved = true;
              *save_status = 0;
              *generation = cred.generation;
              len = vp_http_saved_page(g_response, sizeof(g_response),
                                       cred.ssid, cred.generation,
                                       cred.open_network);
            }
        }
    }

  if (len > 0)
    {
      (void)vp_write_all(fd, g_response, len);
    }
}

static void *vp_thread(void *arg)
{
  (void)arg;

  for (; ; )
    {
      struct pollfd pfd;
      uint32_t generation = 0;
      int save_status = 0;
      bool saved = false;
      bool stopping;
      int fd;
      int ret;

      pthread_mutex_lock(&g_lock);
      stopping = g_server.stopping;
      pthread_mutex_unlock(&g_lock);
      if (stopping)
        {
          break;
        }

      pfd.fd = g_server.listenfd;
      pfd.events = POLLIN;
      pfd.revents = 0;

      /* Polling rather than blocking in accept(): stop() then needs no signal
       * and no socket shutdown trick that may or may not wake accept on a
       * given stack.
       */

      ret = poll(&pfd, 1, VP_ACCEPT_POLL_MS);
      if (ret < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          break;
        }

      if (ret == 0)
        {
          continue;
        }

      fd = accept(g_server.listenfd, NULL, NULL);
      if (fd < 0)
        {
          if (errno == EINTR || errno == ECONNABORTED)
            {
              continue;
            }

          break;
        }

      vp_handle(fd, &saved, &save_status, &generation);

      /* Close before notifying.  The application is expected to leave SoftAP
       * from the callback, and doing that with the response still in flight is
       * what makes a successful save look like a failed submit on the phone.
       */

      shutdown(fd, SHUT_RDWR);
      close(fd);

      if (saved)
        {
          pthread_mutex_lock(&g_lock);
          g_server.generation = generation;
          pthread_mutex_unlock(&g_lock);
        }

      if (saved || save_status < 0)
        {
          if (g_server.on_saved != NULL)
            {
              g_server.on_saved(save_status, generation, g_server.cb_arg);
            }
        }

      if (saved && g_server.one_shot)
        {
          break;
        }

      pthread_mutex_lock(&g_lock);
      stopping = g_server.stopping;
      pthread_mutex_unlock(&g_lock);
      if (stopping)
        {
          break;
        }
    }

  pthread_mutex_lock(&g_lock);
  if (g_server.listenfd >= 0)
    {
      close(g_server.listenfd);
      g_server.listenfd = -1;
    }

  g_server.state = VP_STATE_FINISHED;
  pthread_mutex_unlock(&g_lock);
  return NULL;
}

/* Caller holds g_lock. */

static void vp_reap_locked(void)
{
  if (g_server.state == VP_STATE_FINISHED)
    {
      pthread_t thread = g_server.thread;

      pthread_mutex_unlock(&g_lock);
      pthread_join(thread, NULL);
      pthread_mutex_lock(&g_lock);
      g_server.state = VP_STATE_IDLE;
    }
}

int velasight_provisioning_start(
    const struct velasight_prov_config_s *config)
{
  struct velasight_prov_config_s cfg;
  struct sockaddr_in addr;
  pthread_attr_t attr;
  uint16_t port;
  int one = 1;
  int fd;
  int ret;

  memset(&cfg, 0, sizeof(cfg));
  if (config != NULL)
    {
      cfg = *config;
    }

  if (cfg.store_path != NULL &&
      strlen(cfg.store_path) >= VP_STORE_PATH_MAX)
    {
      return -ENAMETOOLONG;
    }

  pthread_mutex_lock(&g_lock);
  vp_reap_locked();
  if (g_server.state != VP_STATE_IDLE)
    {
      pthread_mutex_unlock(&g_lock);
      return -EALREADY;
    }

  port = cfg.port != 0 ? cfg.port :
         (uint16_t)CONFIG_VELASIGHT_PROVISION_PORT;

  fd = socket(AF_INET, SOCK_STREAM, 0);
  if (fd < 0)
    {
      ret = -errno;
      pthread_mutex_unlock(&g_lock);
      return ret;
    }

  setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));

  memset(&addr, 0, sizeof(addr));
  addr.sin_family      = AF_INET;
  addr.sin_port        = htons(port);
  addr.sin_addr.s_addr = htonl(INADDR_ANY);

  if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0 ||
      listen(fd, 2) < 0)
    {
      ret = -errno;
      close(fd);
      pthread_mutex_unlock(&g_lock);
      return ret;
    }

  g_server.listenfd   = fd;
  g_server.stopping   = false;
  g_server.one_shot   = cfg.one_shot;
  g_server.generation = 0;
  g_server.on_saved   = cfg.on_saved;
  g_server.cb_arg     = cfg.cb_arg;
  snprintf(g_server.store_path, sizeof(g_server.store_path), "%s",
           cfg.store_path != NULL ? cfg.store_path :
           CONFIG_VELASIGHT_PROVISION_STORE);

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, VP_THREAD_STACK);
  ret = pthread_create(&g_server.thread, &attr, vp_thread, NULL);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      close(fd);
      g_server.listenfd = -1;
      pthread_mutex_unlock(&g_lock);
      return -ret;
    }

  g_server.state = VP_STATE_RUNNING;
  pthread_mutex_unlock(&g_lock);

  printf("provision_web: listening on [REDACTED_IP]:%u, store %s\n",
         (unsigned)port, g_server.store_path);
  return 0;
}

int velasight_provisioning_stop(void)
{
  pthread_t thread;

  pthread_mutex_lock(&g_lock);
  vp_reap_locked();
  if (g_server.state != VP_STATE_RUNNING)
    {
      pthread_mutex_unlock(&g_lock);
      return -EALREADY;
    }

  g_server.stopping = true;
  thread = g_server.thread;

  /* Called from the saved callback, which runs on the listener thread: joining
   * ourselves would deadlock, so only ask the loop to end and let the normal
   * exit path close the socket.  A later stop() from the application reaps it.
   */

  if (pthread_equal(thread, pthread_self()))
    {
      pthread_mutex_unlock(&g_lock);
      return 0;
    }

  pthread_mutex_unlock(&g_lock);
  pthread_join(thread, NULL);

  pthread_mutex_lock(&g_lock);
  g_server.state = VP_STATE_IDLE;
  pthread_mutex_unlock(&g_lock);
  return 0;
}

bool velasight_provisioning_is_running(void)
{
  bool running;

  pthread_mutex_lock(&g_lock);
  running = g_server.state == VP_STATE_RUNNING;
  pthread_mutex_unlock(&g_lock);
  return running;
}

uint32_t velasight_provisioning_generation(void)
{
  uint32_t generation;

  pthread_mutex_lock(&g_lock);
  generation = g_server.generation;
  pthread_mutex_unlock(&g_lock);
  return generation;
}

int velasight_provisioning_load_from(
    const char *path, struct velasight_prov_credentials_s *out)
{
  if (path == NULL || out == NULL)
    {
      return -EINVAL;
    }

  return vp_store_load(path, out);
}

int velasight_provisioning_load(
    struct velasight_prov_credentials_s *out)
{
  char path[VP_STORE_PATH_MAX];

  pthread_mutex_lock(&g_lock);
  if (g_server.store_path[0] != '\0')
    {
      snprintf(path, sizeof(path), "%s", g_server.store_path);
    }
  else
    {
      snprintf(path, sizeof(path), "%s", CONFIG_VELASIGHT_PROVISION_STORE);
    }

  pthread_mutex_unlock(&g_lock);

  return velasight_provisioning_load_from(path, out);
}

/****************************************************************************
 * app/provisioning_web/provisioning_web_main.c
 *
 * A console front end for the provisioning service, for bringing it up by
 * hand on a board that has been switched into SoftAP.  Applications should
 * call velasight_provisioning_start() from their own long-lived task instead:
 * the listener runs on a pthread, and a pthread does not outlive the task that
 * created it, so a command that started the service and returned would take
 * the service with it.  That is why this command stays in the foreground.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <errno.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "velasight_provisioning.h"

static volatile bool g_interrupted;

static void provision_usage(void)
{
  printf("usage: provision_web [run [port] [--one-shot]] | show | path\n"
         "\n"
         "  run    serve the provisioning page until Ctrl-C.  port defaults\n"
         "         to %d.  --one-shot returns after the first accepted save.\n"
         "  show   print the stored network, never the passphrase\n"
         "  path   print the store path\n"
         "\n"
         "This service never changes the Wi-Fi role.  Put the board into\n"
         "SoftAP first (see docs/WiFi使用说明.md) and switch back afterwards.\n"
         "The page is plain HTTP with no authentication, so run it only while\n"
         "provisioning.\n",
         CONFIG_VELASIGHT_PROVISION_PORT);
}

static void provision_on_signal(int signo)
{
  (void)signo;
  g_interrupted = true;
}

static void provision_on_saved(int status, uint32_t generation, void *arg)
{
  (void)arg;

  if (status < 0)
    {
      printf("provision_web: save failed: %d\n", status);
      return;
    }

  printf("provision_web: credentials saved, generation %u\n",
         (unsigned)generation);
}

static int provision_show(void)
{
  struct velasight_prov_credentials_s cred;
  int ret;

  ret = velasight_provisioning_load(&cred);
  if (ret == -ENOENT)
    {
      printf("provision_web: nothing provisioned at %s\n",
             CONFIG_VELASIGHT_PROVISION_STORE);
      return EXIT_FAILURE;
    }

  if (ret < 0)
    {
      printf("provision_web: cannot read %s: %d\n",
             CONFIG_VELASIGHT_PROVISION_STORE, ret);
      return EXIT_FAILURE;
    }

  /* Deliberately only whether a passphrase exists.  Printing it would put it
   * into the serial log, which is the one place it is guaranteed to be read by
   * someone who did not need it.
   */

  printf("provision_web: ssid=%s security=%s password=%s generation=%u\n",
         cred.ssid, cred.open_network ? "open" : "wpa2",
         cred.open_network ? "none" : "set",
         (unsigned)cred.generation);
  return EXIT_SUCCESS;
}

static int provision_run(int argc, char *argv[])
{
  struct velasight_prov_config_s cfg;
  struct sigaction sa;
  int i;
  int ret;

  memset(&cfg, 0, sizeof(cfg));
  cfg.on_saved = provision_on_saved;

  for (i = 2; i < argc; i++)
    {
      if (strcmp(argv[i], "--one-shot") == 0)
        {
          cfg.one_shot = true;
        }
      else
        {
          long port = strtol(argv[i], NULL, 10);

          if (port <= 0 || port > 65535)
            {
              printf("provision_web: bad port \"%s\"\n", argv[i]);
              return EXIT_FAILURE;
            }

          cfg.port = (uint16_t)port;
        }
    }

  memset(&sa, 0, sizeof(sa));
  sa.sa_handler = provision_on_signal;
  sigaction(SIGINT, &sa, NULL);

  ret = velasight_provisioning_start(&cfg);
  if (ret < 0)
    {
      printf("provision_web: start failed: %d\n", ret);
      return EXIT_FAILURE;
    }

  printf("provision_web: open http://<board-ip>/ from a device on the "
         "hotspot, Ctrl-C to stop\n");

  while (!g_interrupted && velasight_provisioning_is_running())
    {
      usleep(200000);
    }

  velasight_provisioning_stop();
  printf("provision_web: stopped after %u save(s)\n",
         (unsigned)velasight_provisioning_generation());
  return EXIT_SUCCESS;
}

int main(int argc, FAR char *argv[])
{
  const char *command = argc > 1 ? argv[1] : "run";

  if (strcmp(command, "run") == 0 || strcmp(command, "start") == 0)
    {
      return provision_run(argc, argv);
    }

  if (strcmp(command, "show") == 0)
    {
      return provision_show();
    }

  if (strcmp(command, "path") == 0)
    {
      printf("%s\n", CONFIG_VELASIGHT_PROVISION_STORE);
      return EXIT_SUCCESS;
    }

  provision_usage();
  return EXIT_FAILURE;
}

